(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-feature-cache-skip"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-1\">一 · 事故现场：一次“省算力”把文字画糊了</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-2\">二 · 它到底解决什么：步数线性放大的算力浪费</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-3\">三 · 它不解决什么：三类问题不在射程内</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-4\">四 · 机制为何必须带残差补偿与周期重评估</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-5\">五 · 适用边界的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-6\">六 · 缓存跳步救不了的那一类请求：从一次文字渲染崩坏说起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-7\">七 · 预热步的贡献采样：把“哪块能跳”变成可测数据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-8\">八 · 排序与标记：把分数翻译成计算图</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-9\">九 · 推理步的前向分流：缓存读与计算写的交错</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-10\">十 · 残差补偿：让缓存 feature 对齐当前步分布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-11\">十一 · 周期性重评估：防止分数漂移把缓存集合带偏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-12\">十二 · 与量化、蒸馏叠加时的步骤顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-13\">十三 · 边界条件：缓存命中率之外的三个失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-14\">十四 · 相对残差分数 $s_l$ 的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-15\">十五 · 分段前向表达式的两支与 $\\alpha_l$ 的作用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-16\">十六 · 伪代码：从预热到稳态跳步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-17\">十七 · 阈值 $\\tau_l$ 的标定与重评估周期</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-18\">十八 · 与量化、少步蒸馏叠加时的公式修正</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-19\">十九 · 缓存跳步的边界、失效条件与显存代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-20\">二十 · 请求形态：批量采样才是主战场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-21\">二十一 · 长度分布：步数分布决定收益曲线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-22\">二十二 · 并发与批大小：显存与吞吐的对冲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-23\">二十三 · 负载不对时的三种崩法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-24\">二十四 · 配方落地：按业务切分而不是按全局调参</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-25\">二十五 · 负载配方：请求形态、长度分布与批大小的匹配边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-26\">二十六 · 硬件档位：按缓存容量而不是按算力选卡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-27\">二十七 · 并行拓扑：跳步比例决定并行切分粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-28\">二十八 · 量化方案：缓存精度与计算精度的分离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-29\">二十九 · KV 策略：这里没有 KV，只有 feature 生命周期</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-30\">三十 · 调度参数：阈值、重评估周期与批大小的联合标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-31\">三十一 · 可复现的配置思路：从容量预算倒推</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-32\">三十二 · 部署配方的失效边界：显存档位、阈值漂移与收益反转</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-33\">三十三 · 缓存 feature 的显存账：先于算力崩掉的那一项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-34\">三十四 · 带宽：缓存读回与重算的取舍点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-35\">三十五 · 通信：分离式部署下缓存该放哪一侧</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-36\">三十六 · 功耗与算力密度的错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-37\">三十七 · 尾延迟：P99 由谁决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-38\">三十八 · 规模上限的排序：显存、带宽、通信、功耗的先后</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-39\">三十九 · 缓存常驻显存与规模崩塌点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-40\">四十 · 精度失效的三种指纹与定位手法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-41\">四十一 · OOM 的真实来源：feature 常驻与批内峰值叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-42\">四十二 · 批抖动与路由不均：两个不同层面的失衡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-43\">四十三 · 尾延迟尖刺的三个触发点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-44\">四十四 · 回滚路径：分级降级而非一刀切关闭</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-45\">四十五 · 缓存跳步的失效边界与在线诊断：从画质崩点到显存反噬</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-46\">四十六 · 同族算法的坐标系：改权重、改数值、改计算图</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-47\">四十七 · 决策表：按场景条件选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-48\">四十八 · 与少步蒸馏的耦合：正交但不同步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-49\">四十九 · 与量化的耦合：显存账要先算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-50\">五十 · 与块级稀疏注意力的边界：跳 block 还是跳 token</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-51\">五十一 · 适用条件的量化判据与工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-skip-sec-52\">五十二 · 同族算法怎么选：跳步、蒸馏与量化的边界判据</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:510px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 510.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"428.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">预热若干步，记录每个 block 输出的步间差异作为贡献分数</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"428.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按分数排序，低分 block 标记为可缓存，高分 block 保留计算</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"428.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">推理时缓存 block 读上一步 feature，计算 block 正常前向</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"428.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对缓存 block 施加轻量残差修正（如缩放或低秩补偿）以对齐分布</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"428.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">每 N 步重新评估贡献分数，防止误差漂移</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-feature-cache-skip-sec-1\">一 · 事故现场：一次“省算力”把文字画糊了</h3>\n<p>某条文生图服务线在 B200 单卡上跑一个高步数教师 DiT，请求形态是批量采样、批大小按显存档位取 1–8，SLO 盯的是 P99 端到端时延。为了压时延，工程团队在推理管线里插入了块级跳步：预热若干步后按 block 记录相邻步输出差异，把低贡献 block 标记为可缓存，推理时这些 block 直接读上一步 feature，只对高贡献 block 正常前向。上线初期吞吐确实上去了，直到一批带密集小字的海报请求进来——笔画断裂、文字区域先崩，且后处理锐化与超分都救不回来。事后复盘，根因不是实现 bug，而是阈值 τ 是在另一条业务（风景图、低分辨率）上标定的，跨业务直接复用，导致本该重算的文字相关 block 被误判为低贡献而缓存。这就是本算法最典型的失败模式：它省的是算力，赌的是步间相似度，而相似度依赖 prompt 与分辨率。</p>\n<p>这个事故把问题定义讲清楚了：块级跳步不是“免费加速”，它是一笔用画质换时延的交易，交易能否成立取决于两件事——相邻扩散步的 DiT block 输出是否真的高度相似，以及缓存误差是否被控制在不可见范围内。前者是数据性质，后者是工程控制。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-2\">二 · 它到底解决什么：步数线性放大的算力浪费</h3>\n<p>扩散推理的端到端时延近似随采样步数线性增长：每一步都要把所有 block 全量前向一遍。问题在于，相邻扩散步的 DiT block 输出高度相似——第 t 步与第 t−1 步的中间 feature 差异往往远小于 block 内部计算的量级。这意味着逐步全量计算里有相当一部分是在重算“几乎没变的东西”。高步数教师模型把这种浪费按步数线性放大；视频多帧场景下，帧维再乘一层，时延被进一步放大，成为端到端瓶颈。块级跳步针对的正是这部分冗余：不改权重、不改数值精度，只改前向计算图，把“没怎么变”的 block 从计算图里摘出去。</p>\n<p>形式化地，对第 l 个 block 定义步间相对残差贡献分数：</p>\n<div class=\"formula\">$$s_l=\\frac{\\|h_l^{(t)}-h_l^{(t-1)}\\|_2}{\\|h_l^{(t-1)}\\|_2},\\quad h_l^{(t)}=\\begin{cases}\\alpha_l h_l^{(t-1)}+\\Delta_l &amp; s_l&lt;\\tau\\\\ \\mathrm{Block}_l(h_{l-1}^{(t)}) &amp; s_l\\ge\\tau\\end{cases}$$</div>\n<p>其中 τ 是缓存阈值，α_l 是缩放补偿系数，Δ_l 是低秩残差项。加速比的上界由被跳过的 block 比例决定：</p>\n<div class=\"formula\">$$\\hat{h}_{l}^{t}=h_{l}^{t-1}+\\alpha_{l}\\,\\Delta_{l}^{t},\\quad \\text{Skip if }\\|\\Delta_{l}^{t}\\|&lt;\\tau_{l},\\quad \\text{Speedup}\\approx\\frac{L}{L_{\\text{compute}}}$$</div>\n<p>L 是总 block 数，L_compute 是每步实际重算的 block 数。典型可省 30–50% block 计算，这个区间对应的正是“相似度高、但还没高到可以整步跳过”的中间地带。</p>\n<p>系统代价要算清楚：省下的是 block 级 GEMM 的算力与相应的时间，换来的是缓存 feature 常驻显存。缓存容量按 block 数 × 分辨率 × 批大小预留，KV 概念在这里不适用（DiT 没有自回归 KV cache）。分辨率越高、block 越多，这笔显存开销越大；高分辨率大批量时，缓存占用接近全量计算所需的激活显存，可能抵消吞吐收益——省了算力却先撞上显存墙，这是规模上限受单卡显存约束的直接原因。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-3\">三 · 它不解决什么：三类问题不在射程内</h3>\n<p>第一，它不改模型参数。少步蒸馏是通过改权重把步数压到 4–8 步，量化是改数值精度（FP8/NVFP4），而块级跳步是训练-free 的推理期跳步，只动计算图。因此它无法把“需要 30 步才收敛”的模型变成“4 步就收敛”，它只能在既有步数上做减法。第二，它跳的是整 block 计算，不是 token 间交互。块级稀疏注意力优化的是注意力矩阵里的 token 对，跳步优化的是 block 的前向是否执行，两者正交但不能互相替代——注意力里的冗余不会因为跳了几个 block 就消失。第三，它不解决跨业务泛化。贡献分数依赖 prompt 与分辨率，阈值必须逐业务重新标定；指望一套 τ 打天下，就是第一节那个事故。</p>\n<p>还有一个边界值得单独点出：步数过少时收益收窄。4–8 步采样下，相邻步相似度下降，可缓存的低贡献 block 变少，L_compute 逼近 L，加速比趋近 1，而缓存误差在少步采样下反而更易累积——纹理细节与文字区域先崩。也就是说，本算法与少步蒸馏虽然正交、可叠加，但叠加时的风险不是线性的：蒸馏把步数压得越低，跳步的容错窗口越窄，残差补偿与重评估频率都得跟着收紧。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-4\">四 · 机制为何必须带残差补偿与周期重评估</h3>\n<p>纯缓存的朴素做法是 h_l^(t) = h_l^(t−1)，误差会随步数单调累积：每一步都把上一步的偏差原样带下去，到后段采样时 feature 分布已经偏离计算 block 所期望的输入分布，画质崩坏不可逆。所以机制里必须有两根支柱。其一是残差补偿：对缓存 block 施加轻量修正（缩放 α_l 或低秩补偿 Δ_l）以对齐分布，把“原样复制”变成“带修正的复制”，抑制误差累积。其二是周期重评估：每 N 步重新评估贡献分数，防止误差随步数漂移——早期步的相似度结构不代表后期步，固定一套缓存标记跑完全程会在后段失准。</p>\n<p>伪代码思路按数据流顺序：预热若干步，逐 block 记录相邻步输出差异作为贡献分数；按分数排序，低分 block 标记为可缓存、高分 block 保留计算；推理时缓存 block 读上一步 feature 并施加残差修正，计算 block 正常前向；每 N 步回到评估环节刷新分数。这里的工程代价是预热步本身不省算力，且重评估那一步要额外做一次全量对比，属于固定开销，在短请求上占比不可忽略。</p>\n<p>一个具体例子：视频多帧场景下，帧间与步间双重相似，低贡献 block 比例高，30–50% 的 block 节省能直接反映到 P99 上；但同一套阈值搬到单张文生图、且 prompt 含密集文字时，文字相关 block 的贡献分数被低估，笔画断裂先出现。这说明阈值校准不是一次性动作，而是随业务、分辨率、prompt 分布持续维护的运行时参数。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-5\">五 · 适用边界的工程判断</h3>\n<p>把适用边界压缩成可执行的判断链：先看步数——高步数教师模型是主战场，步数过少则收益收窄且风险上升；再看模态——视频多帧的步间相似度天然高于单帧，收益更稳；再看分辨率与批大小——缓存显存随二者线性增长，需先算清显存账再决定是否开启；最后看业务内容——含文字、细纹理的请求要单独标定更严的 τ，或对这些请求直接关闭跳步。</p>\n<p>部署上它无需重训，可直接插入现有 DiT 推理管线，量化可与 FP8/NVFP4 叠加，硬件档位按显存选卡。真正的工程判断落在两处：一是缓存容量与批大小的取舍，高分辨率大批量下缓存占用接近全量计算，此时跳步的净收益可能为负；二是阈值维护的组织成本，跨业务复用阈值会造成部分请求画质骤降，必须按业务重新标定并纳入发布流程。换句话说，这个算法的上限不由公式决定，而由“你是否愿意为每条业务线维护一套 τ 与重评估周期”决定。</p>\n<p>事故的教训最终落在一个具体机制上：贡献分数是运行时观测量而非模型常量，任何把它当常量写死的实现，都会在业务分布偏移时以画质骤降的形式暴露出来；而残差补偿与每 N 步重评估，正是把这种偏移限制在可见阈值之下的两道闸门。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-6\">六 · 缓存跳步救不了的那一类请求：从一次文字渲染崩坏说起</h3>\n\n<p>线上事故的形态很具体：一条文生图服务在高峰期把批大小从 2 提到 8 以吃满显存档位，同时为了压 P99 时延开启了块级特征缓存。上线当天监控没有报错，吞吐确实上去了，但客服侧开始收到投诉——海报类请求里的中文标题出现笔画断裂，英文小字糊成一团，而同一批次里的风景类请求毫无异常。排查路径最后落在贡献分数上：这批请求的 prompt 里密集排布了文字描述与版式约束，相邻扩散步在这些 block 上的输出差异远高于预热阶段统计出的阈值，但阈值是按上一批以自然图像为主的流量标定的，于是本该重算的 block 被误判为可缓存，直接读了上一步的 feature。误差不是一次性爆掉的，而是在剩余步数里被反复放大，直到文字区域先崩——这正是缓存跳步最典型的失效面：**它假设步间相似度是全局稳定的，而真实流量里相似度是随 prompt 语义、分辨率与批组成漂移的**。</p>\n\n<p>把机制摊开看，问题就清楚了。第 $l$ 个 block 在第 $t$ 步是否跳过，取决于相对残差贡献分数与阈值的比较：</p>\n\n<div class=\"formula\">$$s_l=\\frac{\\|h_l^{(t)}-h_l^{(t-1)}\\|_2}{\\|h_l^{(t-1)}\\|_2},\\quad h_l^{(t)}=\\begin{cases}\\alpha_l h_l^{(t-1)}+\\Delta_l &amp; s_l&lt;\\tau\\\\ \\mathrm{Block}_l(h_{l-1}^{(t)}) &amp; s_l\\ge\\tau\\end{cases}$$</div>\n\n<p>其中 $\\alpha_l$ 是缩放补偿系数，$\\Delta_l$ 是低秩残差项。这个式子的工程含义是：跳过决策是一个**逐 block、逐请求、逐分辨率**的局部判断，而 $\\tau$ 是一个**跨请求共享的全局常数**。一旦流量构成变化，$\\tau$ 就从“保守阈值”退化成“系统性误判源”。更麻烦的是补偿项 $\\alpha_l h_l^{(t-1)}+\\Delta_l$ 只能对齐一阶分布，无法恢复被跳过的非线性变换所携带的高频信息，所以误差表现为细节先丢、结构后坏，且不可通过后处理修复。系统代价上，这条路径的收益是省下 30–50% 的 block 计算，但代价是缓存 feature 常驻显存——按 block 数 × 分辨率 × 批大小预留，高分辨率大批量时显存占用接近全量计算，吞吐收益被显存挤占抵消，甚至反过来压低可承载批大小。</p>\n\n<p>适用边界因此可以画得很硬。它成立的前提是**步间相似度高且稳定**：高步数教师模型、视频多帧这类相邻步共享大量上下文的任务是它的主场，因为步数多意味着单步误差被摊薄、重评估窗口（每 N 步重新评估贡献分数）有足够机会纠偏。它明确不解决的问题有三类。其一，**少步采样场景**：4–8 步时步间相似度本就下降，缓存误差没有足够步数摊薄，收益收窄的同时画质风险陡增，此时它与少步蒸馏叠加虽然正交，但叠加后的误差累积需要单独标定。其二，**跨业务复用**：贡献分数依赖 prompt 与分辨率，直接搬用别的业务阈值会造成部分请求画质骤降，必须逐业务重新校准，这意味着它不是一个可以“一次配置、全站生效”的开关。其三，**显存受限的高分辨率大批量**：缓存容量与计算节省在显存上直接对冲，规模上限受单卡显存约束，超过这个上限就该退回全量计算而不是硬开缓存。它也不改变数值精度路径，量化（FP8/NVFP4）与它是两条独立的优化轴，可以叠加但不能互相替代；它跳的是整 block 计算，与块级稀疏注意力跳过 token 交互是不同层面的动作。</p>\n\n<table class=\"mini\">\n<thead><tr><th>请求形态</th><th>步间相似度</th><th>缓存跳步的工程判断</th></tr></thead>\n<tbody>\n<tr><td>高步数教师模型、自然图像</td><td>高且稳定</td><td>主场，收益可预期，阈值按业务标定一次即可</td></tr>\n<tr><td>视频多帧生成</td><td>高，帧间上下文强</td><td>适用，但需按分辨率分档预留缓存显存</td></tr>\n<tr><td>文字/版式密集 prompt</td><td>局部 block 差异大</td><td>高风险，文字区域先崩，需提高 $\\tau$ 或对该类 block 强制重算</td></tr>\n<tr><td>4–8 步少步采样</td><td>低</td><td>收益收窄、误差易累积，不建议作为主优化手段</td></tr>\n<tr><td>高分辨率 + 大批量</td><td>取决于内容</td><td>缓存显存逼近全量计算，需先算显存账再决定是否开启</td></tr>\n</tbody>\n</table>\n\n<p>工程上真正要守住的判断是：把 $\\tau$ 与 $\\alpha_l$ 当作**按业务、按分辨率、按批组成分别标定的运行参数**，而不是模型常量；把每 N 步的重评估当作误差漂移的兜底，而不是可选项；并且在请求入口做一次轻量的形态判别——文字密集、版式约束强的请求直接走全量计算路径。缓存跳步的价值在于它是训练-free 的推理期计算图改写，插进现有 DiT 管线不需要重训，但它省下的是算力，换走的是**可预测性**；当流量构成不可预测时，这份可预测性的价格就是画质事故。</p>\n<h3 id=\"alg-feature-cache-skip-sec-7\">七 · 预热步的贡献采样：把“哪块能跳”变成可测数据</h3>\n<p>缓存跳步的第一道工序不是推理，而是观测。管线进入正式采样前，先跑若干步全量前向，并在每个 DiT block 的出口挂一个轻量探针：记录该 block 在当前步的输出张量，与上一步同位置输出做逐元素差，再归一化成相对残差分数。这一步的输入是当前步的隐状态与时间步嵌入，输出是一张“block 索引 → 贡献分数”的表，代价是这几步完全不省算力，反而多出一次张量读回与范数计算。</p>\n<p>分数定义沿用相对形式，避免不同 block 激活量级差异导致的阈值失配：</p>\n<div class=\"formula\">$$s_l=\\frac{\\|h_l^{(t)}-h_l^{(t-1)}\\|_2}{\\|h_l^{(t-1)}\\|_2}$$</div>\n<p>工程上不必对整张 feature map 做精确 L2，按通道分组采样或对下采样后的张量求范数即可，误差在排序用途上可接受。真正的代价在显存带宽：每步每 block 要把上一步输出留在片上或 HBM 里做比较，block 数越多、分辨率越高，这份“影子副本”越大。以视频多帧场景为例，批内多帧共享同一组 block 权重但各自持有 feature，探针需要按帧分别统计，否则帧间差异会被平均掉，导致某些帧的细节块被误判为可缓存。</p>\n<p>预热步数是一个显式超参：太少则分数噪声大，排序不稳；太多则吞掉跳步收益。实践中把它与“每 N 步重新评估”共用同一套统计逻辑，预热只是第一次评估。输出侧还要落一份排序结果，高分 block 进入计算集合，低分 block 进入缓存集合，这份集合就是后续所有步的计算图骨架。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-8\">八 · 排序与标记：把分数翻译成计算图</h3>\n<p>拿到分数表后，第二步是按分数升序排列，取低分段标记为可缓存。这里的输入是分数向量与阈值 τ，输出是一张布尔掩码，决定每个 block 在当前步走“读缓存”还是“正常前向”。标记本身几乎零成本，但它决定了后续的算力分配，因此阈值选取是这一段的真正代价所在。</p>\n<p>阈值不能全局固定。贡献分数的分布随 prompt 与分辨率漂移：文字密集的 prompt 会让中后段 block 的分数整体抬升，高分辨率会让浅层 block 的纹理相关残差变大。可行做法是按分位数取阈值，例如把当前步分数的最低一段划入缓存集合，使可缓存 block 的比例成为一个可控旋钮，而不是让 τ 去追分布。这样“省多少算力”变成显式配置，画质风险也随之可预期。</p>\n<p>标记结果要与 block 的计算依赖对齐。DiT 的 block 是串行的，第 l 块读第 l−1 块的输出；若第 l 块被标记为缓存，它读的是上一步自己的输出，而第 l+1 块若被标记为计算，它读的是第 l 块刚刚吐出的缓存 feature。这意味着缓存 block 的输出必须被写回同一块显存位置，供下游计算 block 直接消费，不能留在寄存器里等下一步。写回动作带来一次额外的 HBM 往返，是跳步收益的第一笔固定开销。</p>\n<p>另一个隐性代价是分支发散。同一批内不同请求的分数表不同，缓存集合也不同；若按请求逐条调度，kernel 启动次数随批内差异上升，GPU 利用率被切碎。工程上通常按批内多数请求的缓存集合取并集或交集，用批级掩码换取 kernel 规整，代价是部分请求多算或少算几个 block——少算的那部分正是画质风险的来源。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-9\">九 · 推理步的前向分流：缓存读与计算写的交错</h3>\n<p>正式采样开始后，每一步的前向被拆成两类 block 的交错执行。计算 block 的输入是上游 feature 与当前时间步条件，输出是新 feature，走完整的注意力与 MLP；缓存 block 的输入是上一步自身输出，输出经残差补偿后直接下发。两者在同一计算图里交替，形成“算—跳—算—跳”的节奏。</p>\n<p>分流的关键是时间步条件的处理。缓存 block 跳过了当前步的 AdaLN 调制，等于用上一步的时间步嵌入近似当前步。步间间隔越小，这个近似越成立；高步数教师模型单步跨度小，正是该方法的主场。反过来，少步采样时单步跨度大，时间步条件变化剧烈，缓存 block 的输出分布偏移明显，这也是失败模式里“少步下误差更易累积”的机制根源。</p>\n<p>代价核算要按 block 粒度做。设总 block 数为 L，实际计算数为 L_compute，则理想加速比近似为 L / L_compute；但缓存 block 仍要付出读 feature、做残差补偿、写回下游的带宽成本，所以端到端时延收益低于这个比值。典型可省 30–50% block 计算，落到端到端时延上会被注意力的固定开销与 kernel 启动开销稀释，尤其在批大小取 1–8 的显存档位下，小批量的算力节省更容易被调度开销吃掉。</p>\n<p>具体例子：一个多帧视频采样请求，批内 4 帧、每帧 28 个 block，预热后判定 10 个浅层 block 与 4 个深层 block 可缓存，则每步计算 14 个 block，理想加速比约 2×；实际因缓存写回与批级掩码取并集，计算 block 数回升到 16–18 个，端到端收益落在 1.4–1.6× 区间。这就是为什么部署时要按业务实测而不是按公式外推。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-10\">十 · 残差补偿：让缓存 feature 对齐当前步分布</h3>\n<p>直接复用上一步输出会带来系统性偏差：缓存 block 的输出停留在旧时间步的分布上，下游计算 block 读到的是“过期”输入，误差沿深度累积。补偿的做法是在缓存路径上叠加一个轻量修正，输入是上一步 feature 与可选的残差项，输出是修正后的 feature：</p>\n<div class=\"formula\">$$h_l^{(t)}=\\begin{cases}\\alpha_l h_l^{(t-1)}+\\Delta_l &amp; s_l&lt;\\tau\\\\ \\mathrm{Block}_l(h_{l-1}^{(t)}) &amp; s_l\\ge\\tau\\end{cases}$$</div>\n<p>α_l 是逐 block 的缩放系数，Δ_l 是低秩残差项。缩放补偿最便宜，一次逐元素乘加，带宽代价约等于一次 feature 读写；低秩补偿则要在缓存路径上挂一个小矩阵乘，把上一步 feature 投影到低秩子空间再投影回来，算力开销远小于完整 block 前向，但仍占用 tensor core 周期，且低秩秩数需要按 block 单独标定。</p>\n<p>补偿的收益与风险并存。α_l 偏离 1 太多会让缓存 feature 的幅值漂移，下游注意力的 softmax 温度随之改变，表现为画面整体对比度异常；低秩项若秩数不足，只能修正全局色调而修不了局部纹理，文字区域依旧先崩。工程判断是：浅层 block 用缩放即可，深层 block 若必须缓存则配低秩项，且低秩项只在分数接近阈值时才启用，远离阈值的 block 直接裸缓存以省算力。</p>\n<p>显存代价在这里二次出现：低秩项要常驻权重，α_l 要常驻标量表，缓存 feature 本身要按 block 数×分辨率×批大小预留。高分辨率大批量时，这份常驻占用接近全量计算时的激活占用，可能抵消吞吐收益——这是规模上限受单卡显存约束的直接原因。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-11\">十一 · 周期性重评估：防止分数漂移把缓存集合带偏</h3>\n<p>贡献分数不是常量。随着采样步推进，隐状态从噪声走向结构，哪些 block 在起作用的排序会变化：早期步浅层 block 贡献大，后期步深层 block 贡献上升。若缓存集合一次定死，后期步会把真正需要计算的 block 跳掉，误差不可逆。因此每 N 步要重新评估一次分数，输入是最近若干步的 block 输出差，输出是更新后的缓存集合与阈值。</p>\n<p>重评估的代价是周期性打断跳步节奏：评估步必须全量前向以采集分数，等于每 N 步里有一到两步不省算力。N 越小画质越稳、收益越低；N 越大收益越高、漂移风险越大。工程上把 N 与总步数挂钩，高步数教师模型取较大的 N，少步采样取较小的 N 甚至关闭跳步。重评估还要处理集合切换的瞬态：新集合生效的那一步，原本缓存的 block 突然要计算，其输入是上一步缓存 feature 而非真实前向输出，切换瞬间的误差尖峰需要靠补偿项平滑。</p>\n<p>失败模式的工程含义在此明确：跨业务直接复用阈值会造成部分请求画质骤降，因为分数分布随 prompt 与分辨率漂移，旧阈值在新业务上可能把关键 block 划进缓存。正确做法是每个业务单独标定阈值与 N，把标定结果作为部署配方的一部分固化下来，而不是指望一套超参通吃。纹理细节与文字区域先崩这一现象，本质是这些区域对应 block 的分数在重评估间隔内被低估，且低秩补偿修不回来。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-12\">十二 · 与量化、蒸馏叠加时的步骤顺序</h3>\n<p>该方法不改权重、只改计算图，因此可以与 FP8/NVFP4 量化、少步蒸馏叠加，但叠加顺序影响每一步的代价结构。量化在前：block 前向本身已用低精度 tensor core，计算 block 的算力单价下降，跳步省下的是“低价算力”，相对收益被压缩；但缓存 feature 若也以低精度存储，显存占用与读回带宽同步下降，抵消了部分损失。蒸馏在前：少步采样使步间相似度下降，可缓存 block 比例收缩，跳步收益收窄，此时应把阈值调保守、N 调小。</p>\n<p>步骤顺序上的具体判断是：先量化再跳步，缓存 feature 用与计算一致的精度存储，避免补偿项在精度转换上引入额外误差；若先跳步再量化，缓存路径的低秩补偿要在量化感知下标定，否则 α_l 与 Δ_l 的数值范围会随精度切换而失配。两条路径的端到端时延差异来自缓存写回的带宽：低精度缓存写回更便宜，高精度缓存写回更贵，批大小越大差距越明显。</p>\n<p>最终落在工程判断上：跳步的收益上限由“缓存集合的稳定性”决定，而非由阈值本身决定。分数在重评估间隔内漂移越小，越敢把阈值压低、把 N 拉大；漂移越大，越要靠频繁重评估与保守阈值兜底。部署时把预热步数、阈值分位、N、补偿方式四项一起标定，任何一项单独调优都会在另一项上付出画质或时延代价。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-13\">十三 · 边界条件：缓存命中率之外的三个失效面</h3>\n<p>按数据流顺序看，这套机制真正的代价不在“算得快”，而在“存得下、判得准、补得回”。预热阶段逐 block 记录 $s_l=\\|h_l^{(t)}-h_l^{(t-1)}\\|_2/\\|h_l^{(t-1)}\\|_2$ 需要把每个 block 的上一步输出留在显存里做比对，缓存 block 推理时读的也是这份常驻 feature——容量按 block 数×分辨率×批大小线性增长。高分辨率、批大小取 1–8 的上限档时，缓存 feature 占用接近全量计算所需激活，吞吐收益会被显存带宽与容量双重抵消；此时更优的做法是把批压到 1–2、把省下的显存让给 KV 之外的采样缓冲，而不是硬扛大批量。</p>\n<p>判准问题出在阈值 $\\tau$ 与缩放系数 $\\alpha_l$ 的耦合上。$h_l^{(t)}=\\alpha_l h_l^{(t-1)}+\\Delta_l$（$s_l&lt;\\tau$ 时）里的 $\\alpha_l$ 是对分布漂移的粗对齐，低秩项 $\\Delta_l$ 才承担细粒度补偿；两者若只按单一 prompt 标定，跨业务复用会让部分请求的 $s_l$ 系统性偏低、误判为可缓存，画质骤降。工程上应把 $\\tau$ 与分辨率、步数绑定成一张标定表，每 N 步重估贡献分数时同步刷新 $\\alpha_l$，而不是全局一个常数。</p>\n<p>补不回来的失效最贵：少步采样（4–8 步）下步间相似度本就下降，缓存误差沿 block 链累积，纹理细节与文字笔画先崩，且后处理无法修复笔画断裂。收益公式 $\\text{Speedup}\\approx L/L_{\\text{compute}}$ 只在 $L_{\\text{compute}}$ 稳定时成立；一旦为保画质被迫把高贡献 block 全放回计算路径，$L_{\\text{compute}}$ 抬升，30–50% 的 block 节省迅速收窄。判断标准很直接：若某业务 P99 端到端时延的瓶颈已从算力转到显存容量或画质返工，这套跳步就该退场，改用少步蒸馏改权重，而不是继续调 $\\tau$。</p>\n<table class=\"mini\"><thead><tr><th>失效面</th><th>触发条件</th><th>系统代价</th></tr></thead><tbody><tr><td>显存容量</td><td>高分辨率、批大小接近上限</td><td>缓存 feature 常驻，吞吐收益被抵消</td></tr><tr><td>阈值失配</td><td>跨业务复用同一 $\\tau$</td><td>部分请求画质骤降，需逐业务重标定</td></tr><tr><td>误差累积</td><td>步数降至 4–8</td><td>纹理与文字先崩，后处理不可修复</td></tr></tbody></table>\n<h3 id=\"alg-feature-cache-skip-sec-14\">十四 · 相对残差分数 $s_l$ 的逐项拆解</h3>\n<p>公式的第一项是贡献分数 $s_l$，它不是一个绝对值，而是<b>相对量</b>：分子是相邻两步 block 输出之差的 L2 范数，分母是上一步输出的 L2 范数。这个比值决定了阈值的可移植性——绝对差值会随分辨率、批大小、激活量级整体漂移，而相对量把“这一步这个 block 变了多少”归一化到“相对于它自己的量级”，使得同一个 $\\tau$ 在 512 与 1024 分辨率之间不至于完全失效。分母取 $t-1$ 而非 $t$，是因为推理时 $h_l^{(t)}$ 尚未产生，分数必须在决定是否计算之前就能算出，只能用已知的上一步范数做归一化基准。</p>\n<p>推导的关键一步在于把“跳步是否安全”转化为“跳步引入的误差是否被后续层放大”。设缓存决策在 block $l$ 处引入扰动 $\\epsilon_l=\\alpha_l h_l^{(t-1)}+\\Delta_l-\\mathrm{Block}_l(h_{l-1}^{(t)})$，则下游第 $L$ 层输出的偏差近似为 $\\prod_{j=l+1}^{L}J_j\\cdot\\epsilon_l$，其中 $J_j$ 是第 $j$ 个 block 的雅可比。工程上不去估计雅可比谱，而是用 $s_l$ 作为它的代理：$s_l$ 小意味着该 block 在当前步处于“饱和区”，输入扰动不易被放大，于是 $\\|\\epsilon_l\\|$ 与 $\\prod J_j$ 同时偏小。这就是为什么阈值必须逐 block 而非全局统一——不同深度的 block 对扰动的放大能力不同，浅层 block 的 $s_l$ 通常更小但误差传播路径更长。</p>\n<div class=\"formula\">$$s_l=\\frac{\\|h_l^{(t)}-h_l^{(t-1)}\\|_2}{\\|h_l^{(t-1)}\\|_2},\\quad \\text{Skip if } s_l&lt;\\tau_l$$</div>\n<p>系统代价直接体现在这里：$s_l$ 的计算本身需要一次跨 block 的归约（L2 范数）与一次除法，若在预热阶段逐 block 同步统计，会引入 host-device 同步点，把本来可以异步流水的前向打断。可行做法是把范数统计写进 kernel 的 epilogue，用原子累加写入一块 device 侧分数缓冲，只在预热结束与每 N 步重评估时做一次同步读取。以 1024 分辨率、24 个 block、批大小 4 的 DiT 为例，一次全量前向的激活量级在数百 MB，若每个 block 都同步一次，光同步开销就能吃掉跳步省下的时间，因此分数统计必须做成异步的。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-15\">十五 · 分段前向表达式的两支与 $\\alpha_l$ 的作用</h3>\n<p>第二项是分段函数：$s_l&lt;\\tau$ 时走缓存支 $\\alpha_l h_l^{(t-1)}+\\Delta_l$，否则走计算支 $\\mathrm{Block}_l(h_{l-1}^{(t)})$。注意缓存支的输入是上一步的<b>输出</b>而非上一步的输入，这意味着缓存的是 block 级 feature 而非输入激活，显存占用按 block 数×分辨率×批大小线性增长。$\\alpha_l$ 是缩放补偿系数，$\\Delta_l$ 是低秩残差项，两者共同承担“把上一步的输出拉到当前步分布上”的职责。若 $\\alpha_l=1,\\Delta_l=0$，缓存支退化为纯复制，误差完全依赖 $s_l$ 足够小来兜底；一旦连续多步跳步，误差单调累积，纹理与文字区域最先崩。</p>\n<p>$\\alpha_l$ 的推导来自一阶泰勒展开的截断：设 $h_l^{(t)}\\approx h_l^{(t-1)}+\\frac{\\partial h_l}{\\partial t}\\cdot\\Delta t$，若假设该 block 在当前步的响应近似线性于自身量级，则 $\\alpha_l$ 可取为两步范数比 $\\|h_l^{(t-1)}\\|/\\|h_l^{(t-2)}\\|$ 的滑动估计，把量级漂移吸收进一个标量。$\\Delta_l$ 则用低秩分解 $U_lV_l^{\\top}$ 拟合预热阶段观测到的残差主成分，秩取 4–16 即可覆盖大部分能量。工程判断是：$\\alpha_l$ 便宜（一个标量乘），$\\Delta_l$ 贵（一次低秩 GEMM），因此优先开 $\\alpha_l$，只有在文字区域或高分辨率场景下才为浅层 block 配 $\\Delta_l$。</p>\n<div class=\"formula\">$$\\hat{h}_{l}^{t}=h_{l}^{t-1}+\\alpha_{l}\\,\\Delta_{l}^{t},\\quad \\text{Skip if }\\|\\Delta_{l}^{t}\\|&lt;\\tau_{l},\\quad \\text{Speedup}\\approx\\frac{L}{L_{\\text{compute}}}$$</div>\n<p>加速比公式 $\\text{Speedup}\\approx L/L_{\\text{compute}}$ 是一个上界估计，它假设被跳过的 block 计算时间归零、且 block 间计算量均匀。真实代价来自三处折损：缓存支的读 feature 仍有显存带宽开销（读一个 block 的 feature 与算一个 block 的 GEMM 在算术强度上差一个量级，但在小 batch 下带宽可能成为新瓶颈）；$\\Delta_l$ 的低秩补偿要花时间；跳步造成的不均匀负载让 kernel 启动与流水编排出现气泡。因此在 batch=1、分辨率较低时实测加速比往往低于 $L/L_{\\text{compute}}$ 的名义值，而在 batch 较大、GEMM 已打满时更接近名义值。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-16\">十六 · 伪代码：从预热到稳态跳步</h3>\n<p>把机制落到可实现，需要三个数据结构：每 block 的分数数组 <code>score[L]</code>、每 block 的缓存 feature 环形缓冲 <code>cache[L]</code>（只保留上一步）、以及每 block 的补偿参数 <code>alpha[L]</code> 与低秩因子 <code>U[L],V[L]</code>。预热阶段跑满若干步并逐 block 记录 $s_l$，排序后取分位数确定 $\\tau_l$——注意阈值是按 block 分别定的，不是全局一个数。稳态阶段每个去噪步先读分数决定分支，再在步末更新分数与缓存。</p>\n<ul>\n<li>预热：对 $t=1..T_w$，全量前向，epilogue 异步写 $s_l$ 到 device 缓冲；步末一次性同步，按分位数定 $\\tau_l$，并对高分 block 拟合 $\\alpha_l$ 与低秩 $\\Delta_l$。</li>\n<li>稳态：对每个 block，若 $s_l&lt;\\tau_l$ 则 $\\hat h=\\alpha_l\\cdot\\text{cache}[l]+\\text{lowrank}(U_l,V_l)$，否则正常前向并写回 <code>cache[l]</code>；无论哪支，都把当前输出写入缓存供下一步使用。</li>\n<li>重评估：每 N 步（给定事实中的数字锚点）暂停跳步、全量跑一步，刷新 $s_l$ 与 $\\tau_l$，防止误差随步数漂移。</li>\n<li>降级路径：若连续 K 步某 block 的 $s_l$ 逼近 $\\tau_l$，强制该 block 计算一次，避免临界抖动导致画质闪烁。</li>\n</ul>\n<p>伪代码层面最容易出错的是缓存写入时机：缓存支读的是上一步输出，计算支写的是当前步输出，两者必须在同一个步末统一提交，否则下一步会读到半更新的 feature。实现上用双缓冲加指针交换，避免每步做一次全量拷贝。显存代价在此显式化：<code>cache[L]</code> 常驻显存，容量为 block 数×分辨率×批大小×hidden dim×精度字节数，高分辨率大批量时这部分占用接近全量激活，可能抵消吞吐收益——这正是规模上限受单卡显存约束的直接原因。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-17\">十七 · 阈值 $\\tau_l$ 的标定与重评估周期</h3>\n<p>$\\tau_l$ 不是超参而是<b>标定量</b>：它依赖 prompt 与分辨率，跨业务直接复用会造成部分请求画质骤降。标定方法是在目标业务的一组代表性 prompt 上跑预热，取每个 block 的 $s_l$ 分布的低分位数（例如让 30–50% 的 block 落入缓存支），使跳步比例与画质损失同时可控。给定事实中“典型可省 30–50% block 计算”正是这个分位数的直接结果，而不是先定阈值再反推节省比例。分辨率变化会整体抬高 $s_l$ 的量级，因为高频细节在相邻步间变化更快，因此换分辨率必须重标。</p>\n<p>重评估周期 N 的推导来自误差累积速率的权衡：设每步缓存引入的相对误差为 $\\epsilon$，连续跳步 $k$ 步后累积误差近似 $k\\epsilon$（线性近似，实际因 $\\alpha_l$ 补偿而略低）。若要求累积误差不超过画质可接受上限 $\\epsilon_{\\max}$，则 $N\\le\\epsilon_{\\max}/\\epsilon$。工程上不解析求 $\\epsilon$，而是用“每 N 步全量跑一步”的硬刷新把累积误差截断，N 取 4–8 步量级即可覆盖高步数教师模型的采样区间。代价是刷新步本身不省算力，因此有效加速比要乘以 $(N-1)/N$ 的折损因子。</p>\n<table class=\"mini\"><thead><tr><th>决策点</th><th>机制</th><th>系统代价</th></tr></thead><tbody><tr><td>分数统计</td><td>epilogue 异步原子累加</td><td>同步点若逐 block 做，吃掉跳步收益</td></tr><tr><td>阈值标定</td><td>按业务 prompt 集取分位数</td><td>跨业务复用导致画质不稳</td></tr><tr><td>补偿</td><td>标量 $\\alpha_l$ + 低秩 $\\Delta_l$</td><td>低秩 GEMM 增加单 block 时延</td></tr><tr><td>重评估</td><td>每 N 步全量刷新</td><td>有效加速比乘 $(N-1)/N$</td></tr></tbody></table>\n<p>以视频多帧场景为例：帧间与步间相似度叠加，使 $s_l$ 在多数 block 上长期低于阈值，跳步比例可以推到区间上沿；但一旦镜头切换或运动剧烈，$s_l$ 突增，若阈值未及时重标，缓存支会继续复用旧 feature，表现为运动区域的拖影。这要求把重评估与内容变化检测绑定，而不是死守固定 N 步。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-18\">十八 · 与量化、少步蒸馏叠加时的公式修正</h3>\n<p>当本方法叠加 FP8/NVFP4 量化时，$s_l$ 的分母与分子都带量化噪声，低精度下 $h_l^{(t-1)}$ 的范数估计本身有偏，导致 $s_l$ 在阈值附近抖动。修正办法是在分数统计时用高精度累加器（FP32）计算范数，仅让 feature 本体走低精度存储；这样 $s_l$ 的判定不受量化误差污染，而缓存 feature 的读取仍享受低精度带宽收益。量化与跳步的误差是相乘而非相加的：量化误差在每一步都存在，跳步则把某几步的量化误差冻结并复用，因此低精度下应适当收紧 $\\tau_l$。</p>\n<p>与少步蒸馏叠加时，公式中的 $t$ 跨度变短，相邻步相似度下降，$s_l$ 整体抬升，收益收窄——给定事实明确指出步数过少（如 4–8 步）时相似度下降、收益收窄。此时 $\\text{Speedup}\\approx L/L_{\\text{compute}}$ 的名义值仍成立，但 $L_{\\text{compute}}$ 的实际占比上升，因为更多 block 落入计算支。工程判断是：少步蒸馏负责压低步数，跳步负责压低每步的 block 计算量，两者正交但边际收益递减，叠加时应重标 $\\tau_l$ 而非沿用高步数下的阈值。</p>\n<p>最后落在可实现的一处细节：缓存支的残差补偿若用低秩 $\\Delta_l$，其 GEMM 的 M 维是批大小×序列长度，N/K 维是秩，在 batch=1 时这是一个极度瘦长的 GEMM，算术强度低、受带宽约束，可能比直接算一个完整 block 还慢。因此低秩补偿只在批大小较大或序列较长时开启，小 batch 下退化为纯 $\\alpha_l$ 缩放，把补偿成本压到一个标量乘。这个开关本身就是跳步系统里最值得做自适应的一处。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-19\">十九 · 缓存跳步的边界、失效条件与显存代价</h3>\n<p>把相对残差分数 <span class=\"formula-inline\">s_l = ‖h_l^(t) − h_l^(t−1)‖₂ / ‖h_l^(t−1)‖₂</span> 当作判据，本质是在假设“步间相似度”是块可跳过的充分条件，而这一假设有三个明确的破口。第一，分母归一化让 <span class=\"formula-inline\">s_l</span> 对幅值不敏感：一个幅值很小但方向剧烈翻转的 block 会得到低分而被缓存，误差随后被后续 block 放大；因此阈值 <span class=\"formula-inline\">τ</span> 必须与绝对残差范数联合使用，单看相对分数会在浅层归一化层附近误判。第二，<span class=\"formula-inline\">s_l</span> 是在预热步上统计的，而扩散轨迹的相似度随 <span class=\"formula-inline\">t</span> 非单调变化——高噪声段块输出变化平缓，低噪声段细节块变化陡增，用前几部的分数外推到全轨迹必然失准，这正是“每 N 步重新评估”存在的理由，N 过大则漂移累积，N 过小则评估本身吃掉跳步收益。第三，<span class=\"formula-inline\">α_l</span> 缩放补偿只对齐一阶矩，无法修正缓存块与重算块之间的协方差错配，当相邻两个 block 一跳一算时，接口处的分布偏移会以低秩项 <span class=\"formula-inline\">Δ_l</span> 无法覆盖的高频形式残留。</p>\n<p>失效顺序是可预测的：少步采样（4–8 步）下步间相似度整体下降，<span class=\"formula-inline\">s_l</span> 分布右移，原本安全的 <span class=\"formula-inline\">τ</span> 变成过度激进，缓存误差沿步数逐步累积而非单步爆发；视觉上纹理细节与文字笔画最先崩坏——这两类内容对应高频、低幅值、方向快速变化的特征，恰好落在相对分数判据的盲区，且后处理锐化或超分无法恢复已丢失的笔画拓扑。跨业务复用阈值是第二个失效源：贡献分数依赖 prompt 语义密度与输出分辨率，同一 <span class=\"formula-inline\">τ</span> 在低分辨率批量出图上稳定，换到高分辨率长 prompt 就会让部分请求画质骤降，表现为同批次内质量方差扩大而非整体劣化，这种“部分崩”比“整体糊”更难在 SLO 上被察觉。</p>\n<p>系统代价里最容易被低估的是显存。缓存 feature 常驻显存，容量按 block 数 × 分辨率 × 批大小预留，与 KV cache 无关但同样随序列维度线性增长；高分辨率、大批量（批 1–8 按显存档位取）时缓存占用接近全量计算所需的激活峰值，此时跳步省下的算力换来的吞吐增益会被可用批大小的下降抵消。用一张小表把三档场景的取舍摆清楚：</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>跳步收益</th><th>主要代价</th><th>工程判断</th></tr></thead><tbody><tr><td>高步数教师、视频多帧</td><td>30–50% block 计算</td><td>缓存显存随帧数×分辨率上升</td><td>收益主导，优先启用</td></tr><tr><td>少步蒸馏叠加</td><td>时延进一步压低</td><td>误差累积加速，文字先崩</td><td>需收紧 τ 并缩短 N</td></tr><tr><td>高分辨率大批量</td><td>算力节省被批大小抵消</td><td>缓存占用逼近全量激活</td><td>降批或分块换出缓存</td></tr></tbody></table>\n<p>由此得到的工程判断是：跳步的加速比 <span class=\"formula-inline\">L / L_compute</span> 只在“步间相似度高 + 缓存显存可容纳 + 阈值按业务标定”三者同时成立时才兑现，任何一项失配都会让收益退回甚至为负；部署时应把 <span class=\"formula-inline\">τ</span>、<span class=\"formula-inline\">α_l</span>、N 作为与 prompt 分布和分辨率绑定的运行参数下发，而不是全局常量，并在少步采样路径上默认关闭或仅对高分块保留计算。</p>\n<h3 id=\"alg-feature-cache-skip-sec-20\">二十 · 请求形态：批量采样才是主战场</h3>\n<p>特征缓存与块级跳步的收益不是从单张图里挤出来的，而是从“同一批请求共享同一段步间相似性”里挤出来的。它的天然负载是文生图与视频多帧的批量采样：一个 batch 内多个样本走同一套 block 序列、同一组步数，贡献分数按 block 统计后对整个 batch 生效，跳步决策一次下发、整批复用。批大小按显存档位取 1–8，这不是随意给的区间——缓存 feature 要常驻显存，容量正比于 block 数×分辨率×批大小，批越大，被缓存的中间激活越占地方，能留给计算 block 的显存余量越少。工程上判断一个请求形态是否适配，看的是“批内步间残差分布是否集中”：如果同一 batch 里各样本的 $\\|\\Delta_l^t\\|$ 量级相近，一个阈值 $\\tau$ 就能同时覆盖整批，跳步比例稳定；如果批内样本 prompt 差异极大，残差分布被拉成双峰，阈值只能照顾一半样本，另一半要么被误跳（画质崩）要么被误算（收益归零）。</p>\n<p>视频多帧是这套方法最舒服的形态：帧间与步间双重相似，block 输出的相对残差 $s_l=\\|h_l^{(t)}-h_l^{(t-1)}\\|_2/\\|h_l^{(t-1)}\\|_2$ 天然偏小，低分 block 占比高，$\\text{Speedup}\\approx L/L_{\\text{compute}}$ 里的 $L_{\\text{compute}}$ 被压得很低。代价是缓存容量随帧数线性上涨，多帧场景下显存先于算力成为瓶颈。反过来，单请求、批大小为 1 的交互式出图，跳步带来的时延收益被固定开销（预热若干步的贡献统计、每 N 步的重评估）摊薄，P99 端到端时延的改善远不如批量采样明显。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-21\">二十一 · 长度分布：步数分布决定收益曲线</h3>\n<p>这里的“长度”指采样步数分布，而不是 token 长度。收益随步数单调上升但非线性：步数越多，相邻步的 DiT block 输出越接近，$s_l$ 落在阈值以下的 block 越多，可缓存比例越高。高步数教师模型（几十步量级）是理想负载，逐步全量前向使算力随步数线性放大的问题被直接削掉一段。步数过少（4–8 步）时相似度下降，$s_l$ 普遍抬升，大量 block 被迫回到 $\\mathrm{Block}_l(h_{l-1}^{(t)})$ 分支，收益收窄到接近零，而预热与重评估的固定成本还在，净收益可能为负。</p>\n<p>长度分布的另一面是“分布是否均匀”。服务侧如果混跑短步数与长步数请求，按业务统一标定的阈值会在长步数请求上偏保守、在短步数请求上偏激进。工程做法是按步数分桶：长步数桶用较低 $\\tau$ 换取更高跳步率，短步数桶直接关闭跳步或只对最末几个 block 启用。判断依据是桶内 $s_l$ 的分位数——若某桶 90 分位残差已接近阈值，说明该桶已无跳步空间，继续压阈值只会把纹理细节和文字笔画先推崩。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-22\">二十二 · 并发与批大小：显存与吞吐的对冲</h3>\n<p>并发上升时，缓存 feature 的显存占用按“block 数×分辨率×批大小×并发副本数”叠加。注意 KV 概念在这里不适用——缓存的是 block 级中间激活而非注意力键值，所以不能套用 KV cache 的分页与换出策略，只能按 block 粒度做整块驻留或整块丢弃。批大小从 1 抬到 8，计算 block 的 GEMM 效率提升、单位算力成本下降，但缓存占用同步放大；当缓存占用接近全量计算所需的激活显存时，吞吐收益被显存压力抵消，表现为 batch 上不去、并发被硬卡在显存档位之下。</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{cache}}\\approx N_{\\text{blk}}\\times H\\times W\\times C\\times B\\times d_{\\text{type}}$$</div>\n<p>其中 $N_{\\text{blk}}$ 为被标记可缓存的 block 数，$B$ 为批大小，$d_{\\text{type}}$ 为缓存精度字节数。量化可与 FP8/NVFP4 叠加，把 $d_{\\text{type}}$ 压下来是缓解这条式子的直接手段，但缓存精度下降会放大残差补偿的误差，需要与 $\\alpha_l$ 的标定联动。并发调度的现实约束是：跳步比例高的请求单次前向更短，更容易在连续批处理里被拼进同一 wave，形成“短请求扎堆、长请求排队”的偏斜；调度器若不按预估计算量分桶，P99 会被少数全量计算的长请求拖住。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-23\">二十三 · 负载不对时的三种崩法</h3>\n<p>第一种是少步采样下的误差累积。步数少、步间相似度低，缓存 block 读上一步 feature 的偏差在每一步都被放大一次，残差补偿只能对齐分布、不能恢复丢失的高频信息，纹理细节与文字区域先出现模糊或笔画断裂，且难以通过后处理修复。第二种是跨业务复用阈值。贡献分数依赖 prompt 与分辨率，把一个业务标定好的 $\\tau$ 直接搬到另一个业务，部分请求画质骤降——不是整体劣化，而是特定 prompt 类型（细密文字、高频纹理）整批崩，监控上表现为画质指标的方差突增而非均值下滑。第三种是显存反噬：高分辨率、大批量下缓存 feature 常驻显存接近全量计算，跳步省下的算力被更低的并发度吃掉，端到端吞吐不升反降。</p>\n<ul>\n<li>崩法一：少步采样，误差逐步累积，纹理与文字先崩，后处理不可修复。</li>\n<li>崩法二：阈值跨业务复用，特定 prompt 整批画质骤降，需逐业务重新标定。</li>\n<li>崩法三：高分辨率大批量，缓存显存接近全量计算，吞吐收益被抵消。</li>\n</ul>\n<p>三种崩法的共同点是“负载配方与阈值标定不匹配”，而不是机制本身失效。识别信号很直接：跳步率异常高但画质指标方差同步抬升，说明阈值偏松；跳步率接近零而时延无改善，说明负载步数太少或批内残差分布太散，此时应关掉跳步而不是继续调参。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-24\">二十四 · 配方落地：按业务切分而不是按全局调参</h3>\n<p>可落地的配方是把“请求形态—步数桶—批大小—阈值”绑成一个配置单元，而不是全局一套参数。每个单元内先预热若干步记录贡献分数，按分数排序标记可缓存 block，推理时缓存 block 走 $\\alpha_l h_l^{(t-1)}+\\Delta_l$ 分支、计算 block 走正常前向，每 N 步重新评估一次防止误差随步数漂移。重评估周期 N 是配方里的关键旋钮：N 太小，统计开销吃掉跳步收益；N 太大，prompt 中途语义切换（如多段提示拼接）后旧分数失效，误跳风险上升。工程判断是让 N 与步数桶的长度成比例，长步数桶取较大 N，短步数桶干脆不启用。</p>\n<p>与少步蒸馏正交叠加时，配方要重新标定：蒸馏把步数压到个位数，原本按高步数标定的 $\\tau$ 全部失效，跳步只能在蒸馏后的剩余步里找相似性，收益从 30–50% block 计算往下收。此时更合理的做法是把跳步限制在视频多帧的帧间维度而非步间维度，或直接让位给蒸馏带来的步数削减。最终判断落在一条具体机制上：缓存命中率必须与画质方差联合监控，任一指标越界就回退到该配置单元的全量计算路径，而不是靠调 $\\tau$ 硬撑。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-25\">二十五 · 负载配方：请求形态、长度分布与批大小的匹配边界</h3>\n<p>这套方案的经济性并不来自算法本身，而来自负载与它的相似度假设是否吻合。它吃的是“步间残差小”的红利：第 <em>l</em> 个 block 的贡献分数按相对残差定义，<div class=\"formula\">$$s_l=\\frac{\\|h_l^{(t)}-h_l^{(t-1)}\\|_2}{\\|h_l^{(t-1)}\\|_2},\\quad h_l^{(t)}=\\begin{cases}\\alpha_l h_l^{(t-1)}+\\Delta_l &amp; s_l&lt;\\tau\\\\ \\mathrm{Block}_l(h_{l-1}^{(t)}) &amp; s_l\\ge\\tau\\end{cases}$$</div>阈值 τ 一旦定下，实际加速比就近似为 <em>L</em>/<em>L</em><sub>compute</sub>，其中 <em>L</em><sub>compute</sub> 是被判为高贡献、必须重算的 block 数。于是负载配方的第一性问题变成：这批请求里，有多少 block 的 <em>s<sub>l</sub></em> 会稳定落在 τ 以下。文生图与视频多帧的批量采样是天然匹配形态——同一 prompt 下相邻扩散步的 DiT block 输出高度相似，视频多帧又在时间维上进一步摊薄了单帧的边际计算；而高步数教师模型（几十步量级）把“步数线性放大时延”这个瓶颈暴露得最充分，正是缓存跳步收益最厚的地带。反过来，步数压到 4–8 步的少步蒸馏模型，步间相似度本身下降，可缓存的 block 变少，收益收窄，此时该方案的定位应退为“与蒸馏正交的边际优化”，而不是主力手段。</p>\n<p>批大小与长度分布要按显存档位来配，而不是按吞吐愿望来配。缓存 feature 常驻显存，容量需求大致随 block 数 × 分辨率 × 批大小线性增长；批大小取 1–8 的区间，本质是让“缓存常驻 + 计算 block 的激活”两者之和留在单卡显存预算内。这里没有 KV cache 的概念可用，不能拿 PagedAttention 那套分页腾挪来救场——feature 是按 block 整块驻留的，粒度粗、无法按 token 增量回收。因此长度分布的影响是间接的：分辨率越高、block 越多，缓存开销越大，规模上限被单卡显存直接卡死；当高分辨率叠加大批量时，缓存占用接近全量计算的水平，吞吐收益被显存压力抵消，甚至因为可用批大小被迫下调而净亏。请求形态上还应区分“同 prompt 批量采样”与“异构 prompt 混批”：前者步间相似度一致、阈值校准一次即可覆盖整批；后者每个请求的贡献分数分布不同，混批会把最保守的那个请求的 τ 拖累整批的跳步率。</p>\n<p>负载不对时的失效是渐进且不可逆的。少步采样下缓存误差更易累积，纹理细节与文字区域最先崩——模糊与笔画断裂出现在高频结构上，且难以通过后处理修复，因为丢的是中间 feature 的信息而非最终像素的噪声。跨业务直接复用阈值同样危险：贡献分数依赖 prompt 与分辨率，一套在风景图上标定好的 τ 搬到含密集文字的电商图上，会造成部分请求画质骤降。工程上的对策是把 τ 与 α<sub>l</sub>、Δ<sub>l</sub> 一起当作“按业务标定的配置项”，并把每 N 步重新评估贡献分数作为兜底——它既是防误差随步数漂移的手段，也是负载漂移的探测器：若重评估发现高分 block 比例上升，说明当前负载已偏离配方，应回退到全量计算或调低跳步率。容量规划时把 P99 端到端时延作为主 SLO，用 30–50% block 计算的节省去换更大的批或更高的分辨率，而不是去换更低的单请求延迟——后者在批内会被最慢请求的缓存失效拖平。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>匹配度</th><th>系统代价表现</th></tr></thead><tbody><tr><td>高步数教师模型、同 prompt 批量采样</td><td>高</td><td>省 30–50% block 计算，P99 时延下降</td></tr><tr><td>视频多帧、步间相似度高</td><td>高</td><td>时延随步数线性放大的部分被削平</td></tr><tr><td>少步蒸馏（4–8 步）</td><td>低</td><td>相似度下降、收益收窄，误差更易累积</td></tr><tr><td>高分辨率 + 大批量</td><td>受显存约束</td><td>缓存常驻接近全量，吞吐收益被抵消</td></tr><tr><td>异构 prompt 混批、跨业务复用 τ</td><td>失效</td><td>画质骤降，需逐业务重标定</td></tr></tbody></table>\n<h3 id=\"alg-feature-cache-skip-sec-26\">二十六 · 硬件档位：按缓存容量而不是按算力选卡</h3>\n<p>特征缓存跳步把成本从“算”挪到了“存”，选卡逻辑因此要反过来。全量前向时，显存压力主要来自权重与激活峰值；插入块级跳步后，每个被标记为可缓存的 block 都要在显存里常驻一份上一步输出，容量随 block 数、token 数（分辨率）与批大小三者相乘增长。工程上先算这笔账，再谈算力档位。</p>\n<div class=\"formula\">$$M_{\\text{cache}} \\approx N_{\\text{skip}} \\cdot S_{\\text{tok}} \\cdot B \\cdot d_{\\text{model}} \\cdot b_{\\text{bytes}}$$</div>\n<p>其中 $N_{\\text{skip}}$ 是被标记为可缓存的 block 数，$S_{\\text{tok}}$ 是潜空间 token 数，$B$ 是批大小，$b_{\\text{bytes}}$ 是每元素字节数。以 FP16 缓存为例，$b_{\\text{bytes}}=2$；若缓存以 FP8 保存，容量减半，但残差补偿项要在更高精度下计算，否则缩放系数 $\\alpha_l$ 与低秩项 $\\Delta_l$ 的量化误差会直接进入下一步的 feature。这条约束决定了档位划分：单卡显存足够容纳“权重 + 激活峰值 + 缓存”三块，才谈得上把 $N_{\\text{skip}}$ 开到有意义的比例；显存吃紧时，先降批大小，再降缓存精度，最后才降 $N_{\\text{skip}}$，因为跳步比例直接决定收益上限。</p>\n<p>具体例子：一个潜空间分辨率对应 token 数较大的视频多帧请求，批大小取 1–8 区间的高位，缓存若以 FP16 常驻，$N_{\\text{skip}}$ 开到总 block 数的一半时，缓存占用会与权重同量级，此时激活峰值反而成了次要项。工程判断是：高分辨率、大批量场景下缓存占用接近全量计算时的激活开销，吞吐收益可能被显存挤占抵消——这正是失败模式之一，选卡时必须先做容量预算而不是先看 TFLOPS。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-27\">二十七 · 并行拓扑：跳步比例决定并行切分粒度</h3>\n<p>块级跳步在并行拓扑上引入一个新约束：同一步内，被缓存的 block 与计算的 block 走的是不同数据路径，前者是显存读，后者是 MMA 与 TMEM 密集计算。若把整段 block 序列按层切分到多卡，缓存 block 所在的卡几乎不干活，计算 block 所在的卡成为瓶颈，负载严重倾斜。因此拓扑设计要把“每张卡上的计算 block 数”尽量配平，而不是简单按层数均分。</p>\n<p>伪代码思路：给定贡献分数排序后的 block 列表，按分数降序做贪心装箱，把高分 block 均匀撒到各卡，低分 block 作为填充项补齐每卡的 block 总数；每 N 步重新评估贡献分数后重跑一次装箱，因为分数漂移会让原本均衡的切分失衡。重评估周期与装箱开销要一起计入调度预算——装箱本身是毫秒级的排序与分配，但若每步都做，调度开销会吃掉跳步收益。</p>\n<p>代价侧写：张量并行下，被缓存的 block 仍需参与集合通信吗？不需要，因为它的输出直接来自本地显存，但计算 block 的 all-reduce 仍在关键路径上，跳步减少的是计算量而非通信轮次，通信占比因此上升。当跳步比例高到一定程度，通信成为端到端时延的主项，此时应转向更粗的切分（如按 stage 切分而非按层切分），把缓存 block 集中到少数卡上，让计算卡之间的通信域变小。具体例子：NVL72 域内 NVLink 5 带宽充裕，跨节点则不然，因此跳步比例高的部署应优先把计算 block 压在单节点内，缓存 block 可以外溢到相邻节点，用 NIXL 做 feature 的远端读取——但远端读的延迟要计入 P99，不能只看平均。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-28\">二十八 · 量化方案：缓存精度与计算精度的分离</h3>\n<p>量化与跳步正交，但两者叠加时有一个非对称性：计算 block 走 FP8 或 NVFP4 的 GEMM，缓存 block 只做一次显存读加轻量残差修正。这意味着缓存侧的精度需求低于计算侧——缓存只需保住 feature 的分布形状，不需要保住 GEMM 的数值细节。于是配方是：计算路径用 NVFP4/FP8 混合精度（细节见本模块量化条目），缓存路径用 FP8 存储、FP16 做残差补偿。</p>\n<div class=\"formula\">$$\\hat{h}_{l}^{t}=h_{l}^{t-1}+\\alpha_{l}\\,\\Delta_{l}^{t},\\quad \\text{Skip if }\\|\\Delta_{l}^{t}\\|&lt;\\tau_{l},\\quad \\text{Speedup}\\approx\\frac{L}{L_{\\text{compute}}}$$</div>\n<p>残差项 $\\Delta_l^t$ 的低秩补偿若在 FP8 下计算，缩放系数 $\\alpha_l$ 的舍入会累积到后续步；把 $\\alpha_l \\Delta_l^t$ 这一项抬到 FP16 计算，代价只是每个缓存 block 多一次小规模矩阵乘，相对整 block 前向可忽略。量化方案的另一处交互是阈值 $\\tau_l$：NVFP4 下 block 输出的量化噪声本身就会抬高步间差异的基线，若沿用 FP16 下校准的阈值，会把本可缓存的 block 误判为需计算，跳步比例被动下降。校准阈值时必须在目标量化精度下做，而不是在 FP16 下校准后直接套用。</p>\n<p>具体例子：同一 prompt 在 FP16 与 NVFP4 两种计算精度下，同一 block 的步间相对残差分数 $s_l$ 会因量化噪声而系统性偏高，导致按 FP16 标定的 $\\tau$ 在 NVFP4 部署中过于保守。工程做法是把阈值校准与量化方案绑定成一组配置，换量化就重标定，这条规则写进部署清单而不是留给现场调参。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-29\">二十九 · KV 策略：这里没有 KV，只有 feature 生命周期</h3>\n<p>扩散 DiT 的自注意力不维护自回归 KV cache，KV 概念在本方法中不适用，取而代之的是 feature 的生命周期管理。缓存 block 的 feature 在一步内被读取一次、在下一次重评估时可能被替换，生命周期短、复用次数少，因此不能用 KV cache 那套按 token 分页、按请求持有的管理方式，而应按“步”做环形缓冲：每步写入当前步的缓存 feature，上一步的缓冲在写入完成后释放。</p>\n<p>显存代价的第二个来源是预热阶段：预热若干步要记录每个 block 的步间差异，这需要同时持有相邻两步的 block 输出，峰值是稳态的两倍。预热只在请求开始时发生一次，但批内多请求若同时预热，峰值叠加。调度上应把预热错峰，或对小批请求合并预热，避免预热峰值成为显存规划的约束项。具体例子：批大小 8 的请求若同时进入预热，相邻两步 feature 同时驻留，显存峰值远超稳态；把批拆成两波、错开预热步，峰值回落到稳态水平，代价是首 token 时延略微上升，但 P99 更可控。</p>\n<p>另一条策略是缓存 feature 的放置：常驻显存还是落回 host？落回 host 会引入 PCIe 往返，单次读取延迟远高于显存读，且与计算 block 的前向无法重叠，P99 会被拖长。结论是缓存必须常驻显存，host 侧只保留贡献分数这类元数据。这也回到第一节的容量预算：显存不够时降批大小，而不是把 feature 换出。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-30\">三十 · 调度参数：阈值、重评估周期与批大小的联合标定</h3>\n<p>调度参数不是独立可调的旋钮，三个参数互相牵制：阈值 $\\tau_l$ 决定跳步比例，重评估周期 $N$ 决定分数漂移的跟踪精度，批大小决定显存余量与预热峰值。标定顺序应是先定批大小（由显存档位与 SLO 决定），再在目标批大小下标定 $\\tau_l$，最后用 $N$ 控制漂移。</p>\n<ul>\n<li>阈值 $\\tau_l$：按 block 分别标定而非全局统一。浅层 block 的步间差异通常小于深层，统一阈值会让浅层过度缓存、深层过度计算，收益与画质两头不讨好。按业务分别标定，跨业务复用阈值是画质骤降的直接原因。</li>\n<li>重评估周期 $N$：太小则调度开销占比上升，太大则分数漂移导致缓存 block 误判。少步采样场景下步数本就少，$N$ 应取小值甚至每步重评估，因为此时误差累积最快；高步数教师模型下 $N$ 可取较大值。</li>\n<li>批大小：与跳步比例反向相关。跳步比例高时单请求显存占用上升，批大小要相应下调以守住显存预算；跳步比例低时缓存占用小，批大小可放大以摊薄权重读取。</li>\n</ul>\n<p>代价侧写：跳步带来的 30–50% block 计算节省并不等价于端到端时延同比例下降，因为被跳过的 block 省下的是计算时间，而剩余 block 的显存读、通信与调度开销不变，Amdahl 意义上端到端收益低于计算节省比例。SLO 以 P99 端到端时延为主时，要按端到端口径验证，而不是按 block 计算量口径宣称收益。具体例子：一个高步数教师模型请求，跳步比例开到中位，端到端时延下降幅度明显小于计算节省比例，差额主要来自重评估与装箱的调度开销以及通信占比上升；把 $N$ 调大后差额收窄，但画质在长步数尾部出现漂移，需要在这条曲线上找业务可接受的拐点。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-31\">三十一 · 可复现的配置思路：从容量预算倒推</h3>\n<p>把上述约束串成一条可复现的配置流程，顺序是容量、拓扑、量化、调度，每一步的输出是下一步的输入，避免在现场反复试错。</p>\n<ul>\n<li>第一步，容量预算：按目标分辨率与批大小算出 $M_{\\text{cache}}$，加上权重与激活峰值，确认落在单卡显存内并留出预热峰值的余量。不满足则先降批大小。</li>\n<li>第二步，拓扑装箱：按贡献分数降序把计算 block 均匀分配到各卡，缓存 block 作为填充；确认计算卡之间的通信域在单节点内，缓存读取路径不跨慢链路。</li>\n<li>第三步，量化绑定：计算路径定 FP8/NVFP4，缓存路径定 FP8 存储加 FP16 残差补偿；在该精度下重新标定 $\\tau_l$，不沿用其他精度的标定值。</li>\n<li>第四步，调度标定：在目标批大小与量化方案下扫 $\\tau_l$ 与 $N$，以 P99 端到端时延与画质指标（纹理细节、文字区域）双目标取拐点；跨业务部署时按业务重跑本步。</li>\n<li>第五步，稳定性看护：把贡献分数漂移、缓存命中比例、预热峰值显存三项做成运行时指标，漂移超限时触发重标定而不是静默降级。</li>\n</ul>\n<p>这条流程的工程判断落在最后一步：跳步是训练-free 的推理期改动，收益来得快，但阈值与量化、分辨率、业务强绑定，任何一项变更都要重走标定。把标定做成配置项而非代码分支，才能让同一套管线在不同业务间复用而不牺牲画质稳定性。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-32\">三十二 · 部署配方的失效边界：显存档位、阈值漂移与收益反转</h3>\n<p>把块级跳步装进生产管线，配置顺序应当反过来做：先按显存档位定批大小与分辨率上限，再定并行拓扑，最后才调阈值。原因是缓存 feature 的常驻开销与 block 数、分辨率、批大小三者同时成正比，而收益只与可跳过的 block 比例成正比。设单 block 单样本 feature 显存为 $m$，则缓存池容量约为 $B\\cdot N_{\\text{blk}}\\cdot m$，其中 $B$ 为批大小；当分辨率翻倍、block 数随之增加时，这块开销会迅速逼近全量激活占用，吞吐收益被显存容量直接吃掉。工程上应把批大小按显存档位取 1–8，高分辨率视频多帧场景取低档，量化方案与 FP8/NVFP4 叠加时优先压缩权重与激活，缓存池单独核算，不与 KV 概念混用——本方法不存在 KV cache，缓存的是 block 输出而非 token 状态。</p>\n<p>阈值 $\\tau$ 与补偿系数 $\\alpha_l$ 不是全局常量，而是随 prompt 与分辨率漂移的业务参数。判定式为 $s_l=\\|h_l^{(t)}-h_l^{(t-1)}\\|_2/\\|h_l^{(t-1)}\\|_2$，当 $s_l&lt;\\tau$ 时走 $\\alpha_l h_l^{(t-1)}+\\Delta_l$ 的缓存路径，否则正常前向。跨业务直接复用一组阈值，会让部分请求的画质骤降：文字区域与高频纹理的步间残差本就偏大，一旦被误判为低贡献，笔画断裂与模糊先出现，且后处理无法修复。因此每个业务线必须独立标定，标定成本应计入上线预算，而不是当作一次性调参。</p>\n<table class=\"mini\"><thead><tr><th>配置维度</th><th>取值策略</th><th>失效条件</th></tr></thead><tbody><tr><td>批大小</td><td>按显存档位 1–8，高分辨率取下限</td><td>缓存池占用接近全量激活，吞吐收益反转</td></tr><tr><td>重评估周期 N</td><td>固定步数间隔重算贡献分数</td><td>N 过大，误差随步数漂移累积</td></tr><tr><td>采样步数</td><td>高步数教师模型优先启用</td><td>4–8 步时相似度下降，收益收窄</td></tr><tr><td>阈值来源</td><td>逐业务、逐分辨率标定</td><td>跨业务复用，画质不稳</td></tr></tbody></table>\n<p>并行拓扑上，本方法只改前向计算图、不改权重，因此可与张量并行、序列并行自由组合，但跳步带来的负载不均衡会被放大：同一 batch 内不同样本的可缓存 block 集合不同，若按 block 做流水划分，计算 block 集中的阶段会成为气泡源。更稳的做法是按样本维度切分并把重评估周期 N 对齐到调度边界，使每个调度窗口内的计算量可预测。收益上限由 $\\text{Speedup}\\approx L/L_{\\text{compute}}$ 给出，典型可省 30–50% block 计算，与少步蒸馏正交叠加后进一步压低端到端时延；但一旦步数降到 4–8 步，步间相似度下降使 $L_{\\text{compute}}$ 回升，跳步收益收窄，此时应关闭跳步、把预算让给蒸馏与量化，而不是硬调低阈值去凑加速比。</p>\n<h3 id=\"alg-feature-cache-skip-sec-33\">三十三 · 缓存 feature 的显存账：先于算力崩掉的那一项</h3>\n<p>块级跳步把“省算力”换成了“占显存”，这笔交换在低分辨率小批量下几乎无感，一旦分辨率与批大小同时上去，显存会先于算力成为约束。机制上很直接：被标记为可缓存的 block 需要在整条采样轨迹上持有上一步输出 $h_l^{(t-1)}$，其形状为 $[B,\\,N_{\\text{tok}},\\,C]$，其中 $N_{\\text{tok}}$ 随分辨率平方增长。于是缓存常驻容量可写成</p>\n<div class=\"formula\">$$M_{\\text{cache}}\\approx \\sum_{l\\in\\mathcal{C}} B\\cdot N_{\\text{tok}}\\cdot C\\cdot b_{\\text{bytes}}\\cdot \\big(1+\\kappa_{\\text{res}}\\big)$$</div>\n<p>$\\mathcal{C}$ 为缓存 block 集合，$b_{\\text{bytes}}$ 是 feature 的字节宽度（FP16 为 2、BF16 为 2、FP8 为 1），$\\kappa_{\\text{res}}$ 是残差补偿项（缩放系数几乎不占空间，低秩补偿则要额外存一对低秩因子，量级远小于主 feature 但仍需计入）。工程判断的关键在于：缓存集合大小不是固定值，它由贡献分数排序动态决定，而分数又依赖 prompt 与分辨率——这意味着显存预算必须按“最坏情况缓存集合”预留，否则运行时会因阈值放宽而 OOM。</p>\n<p>具体例子：一条 1024×1024 的 DiT 采样，patch 尺寸取常见的 2×2，则 $N_{\\text{tok}}$ 在万级；若批大小取 4、block 通道数在千级、缓存 12 个 block、feature 用 BF16，缓存常驻量会达到数 GB 量级，与模型权重和激活峰值叠加后，单卡显存档位直接被抬高一级。此时即便 block 计算省了 30–50%，端到端吞吐也可能因为批大小被迫从 8 降到 4 而回落——省下的算力被显存挤掉的并发吃掉。这是本方法在规模上最先崩的一环，也是部署配方里“按 block 数×分辨率×批大小预留容量”那句话的真实含义。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-34\">三十四 · 带宽：缓存读回与重算的取舍点</h3>\n<p>跳过一个 block 并不等于零代价，它把“算”换成了“读”。缓存 block 的路径是：从显存读回 $h_l^{(t-1)}$，施加残差修正，写入下一层输入。计算 block 的路径是：读输入、做 MMA、写输出。两条路径的字节量在同量级，差别在于计算 block 还要额外承担权重读取与 TMEM 往返。于是单 block 的带宽代价可以粗写成</p>\n<div class=\"formula\">$$\\text{BW}_{\\text{skip}}\\approx \\frac{2\\,B N_{\\text{tok}} C\\,b_{\\text{bytes}}}{t_{\\text{step}}},\\qquad \\text{BW}_{\\text{compute}}\\approx \\text{BW}_{\\text{skip}}+\\frac{W_l}{t_{\\text{step}}}$$</div>\n<p>其中 $W_l$ 为该 block 的权重字节数。在 Blackwell 上，HBM 带宽是共享资源，跳步把压力从“权重流”转移到“激活流”。对于权重占比高的 block（通道宽、kernel 大），跳步确实减压；但对于本身激活主导的浅层 block，跳步省下的权重流量有限，反而多了一次显式读回与写回，带宽账可能持平甚至略亏。这就是为什么贡献分数排序不能只看残差大小，还要看 block 的算术强度：低算术强度、激活主导的 block 即使残差小，跳步的净收益也薄。</p>\n<p>更隐蔽的一层是残差修正的访存模式。缩放补偿 $\\alpha_l h_l^{(t-1)}$ 是一次逐元素乘，能融进读回 kernel，代价可忽略；低秩补偿 $\\Delta_l = U_l V_l^{\\top}$ 则是两次小 GEMM，虽然 FLOPs 小，但它打断了原本连续的 feature 流，引入了额外的 kernel 启动与同步点。在连续批处理下，这些同步点会放大尾延迟——单个请求的跳步路径上多出若干个微型 kernel，调度器难以把它们与其他请求的算力重叠填满。规模上去后，这类“碎片化 kernel”对 SM 占用率的侵蚀，往往比省下的那点 FLOPs 更值得关注。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-35\">三十五 · 通信：分离式部署下缓存该放哪一侧</h3>\n<p>在预填/解码分离或跨节点扩散服务里，block feature 缓存的位置直接决定通信量。三种放置各有代价：其一，缓存留在计算侧显存，请求被调度到哪张卡就在哪张卡上重建缓存，跨卡迁移时缓存作废、需要重新预热若干步，等价于一次冷启动；其二，缓存随请求走，通过 NVLink 或 NIXL 在阶段间搬运，搬运量正比于 $\\sum_{l\\in\\mathcal{C}} B N_{\\text{tok}} C b_{\\text{bytes}}$，在 NVL72 域内 NVLink 5 尚可承受，跨域走 RDMA 则会把这一步变成带宽瓶颈；其三，缓存集中存放在旁路存储池，计算侧按需拉取，延迟被拉长到微秒级以上，对高步数轨迹尚可摊薄，对少步采样则是灾难。</p>\n<p>工程上的判断是：缓存的生命周期与请求绑定，而请求在分离式架构里会被反复重调度，因此缓存亲和性调度（把同一请求的连续若干步钉在同一组 GPU 上）比缓存本身的技术实现更重要。若调度器不做亲和，跳步的收益会被反复预热抵消——预热若干步本身就是全量计算，等于把省下的 block 计算又还回去一部分。这一点在视频多帧场景下被放大：帧间还要保持时序一致，缓存跨帧复用会引入额外的一致性约束，通信与同步开销随帧数线性上升。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-36\">三十六 · 功耗与算力密度的错配</h3>\n<p>跳步降低的是瞬时算力需求，但功耗并不会等比例下降。Blackwell 的功耗大头在 HBM 与供电转换，SM 侧的动态功耗只占一部分。当一批 block 被跳过，SM 的利用率下降，但 HBM 仍要服务缓存读回与其余 block 的权重流，整卡功耗曲线变得平坦而低效——单位功耗完成的有效 token 数反而可能变差。这在容量规划里表现为：按峰值算力选的电源与散热配置，在跳步负载下出现“算力闲置但功耗不降”的区间，PUE 与机架功率预算的余量被浪费。</p>\n<p>更实际的影响在批调度层。连续批处理依赖 SM 被持续填满来摊薄尾延迟；跳步让部分 block 提前退出计算，SM 出现空洞，调度器需要用其他请求的 block 填补。若批内请求的缓存集合差异大（不同 prompt 触发不同阈值判定），批内计算图变得不规则，GEMM 的合并效率下降，tcgen05 的 2-SM MMA 配对也可能被打散。规模上去后，这种不规则性会先于显存或带宽成为吞吐的隐形天花板：不是某个资源耗尽，而是资源利用率的结构性下滑。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-37\">三十七 · 尾延迟：P99 由谁决定</h3>\n<p>SLO 以 P99 端到端时延为主时，跳步的收益分布是不均匀的。平均时延因 30–50% 的 block 计算节省而下降，但 P99 由最慢的那批请求决定，而这批请求恰恰可能是缓存判定失败、阈值未命中、需要回退全量计算的请求。回退路径的代价是双份的：已经读回的缓存 feature 作废，block 重新走完整前向，且此前若干步的残差补偿误差已经累积，画质与一致性都要靠后续步数修补。伪代码层面的判定可以写成</p>\n<div class=\"formula\">$$\\text{step}(t):\\ \\forall l,\\ s_l=\\frac{\\|h_l^{(t)}-h_l^{(t-1)}\\|_2}{\\|h_l^{(t-1)}\\|_2};\\ \\text{if } s_l\\ge\\tau_l \\Rightarrow \\text{recompute}_l;\\ \\text{every } N \\text{ steps} \\Rightarrow \\text{rescore}$$</div>\n<p>尾延迟的来源有三：一是重打分周期 $N$ 到达时，整批请求同时触发分数重估，形成周期性尖峰；二是跨业务复用阈值导致的判定抖动，同一批内部分请求频繁在缓存与重算之间切换；三是少步采样下误差累积触发的画质补救（例如追加步数或提高分辨率重跑），这类补救不在原 SLO 预算内。工程上可行的做法是把重打分错峰到不同请求的轨迹相位上，避免 $N$ 步对齐造成的同步尖峰；同时给阈值判定加滞回（hysteresis），让 $s_l$ 在 $\\tau_l$ 附近不反复翻转，牺牲一点算力节省换取尾延迟的稳定。</p>\n<p>具体例子：视频多帧采样中，帧间相似度高使多数 block 被判为可缓存，平均时延显著下降；但运动剧烈或文字出现的帧会集中触发重算，这些帧的时延抬高了整段视频的 P99。若按平均时延做容量规划，机架会在这些帧上出现排队堆积——这正是“规模上去以后哪里先崩”的答案之一：不是平均吞吐，而是尾部的判定抖动与重打分同步。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-38\">三十八 · 规模上限的排序：显存、带宽、通信、功耗的先后</h3>\n<p>把四类代价按规模排序，可以得到一条工程判断链。第一崩的是显存：缓存常驻量与分辨率、批大小、缓存集合大小三者相乘，最先触碰单卡上限，直接压缩批大小并反噬吞吐。第二崩的是带宽：当批大小被显存压到低位，单请求的激活读回占比上升，跳步从“省权重流”退化为“多一次激活往返”，净收益变薄。第三崩的是通信：分离式部署下缓存亲和性不足导致反复预热，跨域搬运把 NVLink 域内的优势抹平。功耗与算力密度错配则贯穿始终，表现为机架功率预算下的有效吞吐不达标，而非某个硬性报错。</p>\n<p>对应的容量规划动作也就明确了：按最坏缓存集合预留显存、按 block 算术强度而非仅残差排序决定缓存集合、按请求亲和性做调度、按 P99 而非均值定 SLO 余量。规模上限受单卡显存约束这句话不是定性搪塞，它指向一个可计算的边界：当 $M_{\\text{cache}}$ 与权重、激活峰值之和超过档位容量时，唯一的出路是缩小缓存集合（提高阈值、牺牲画质）或降低批大小（牺牲吞吐），二者都在削弱本方法的初衷。真正的规模扩展要靠把缓存集合从“全轨迹常驻”改为“按需重建 + 低秩压缩”，把显存账从 $O(L\\cdot B N_{\\text{tok}} C)$ 压到 $O(|\\mathcal{C}|\\cdot r)$ 量级，代价是重建时的额外计算与一致性风险——这是本方法在超大规模下必须面对的取舍点。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-39\">三十九 · 缓存常驻显存与规模崩塌点</h3>\n<p>块级跳步把算力换成了显存驻留：每个被标记为可缓存的 block 都要保留上一步的 feature 张量，容量按 block 数×分辨率×批大小线性叠加。以视频多帧采样为例，单请求要同时驻留多帧、多层、多通道的中间激活，批大小按显存档位取 1–8 时，缓存占用会随批大小成倍放大。一旦缓存 feature 常驻显存接近全量计算的激活峰值，剩余显存就不足以支撑计算 block 的前向与算子 workspace，调度器只能降批或回退全量路径，吞吐收益被抵消。此时先崩的不是算力而是显存容量：跳步比例越高、分辨率越大，可缓存 block 越多，显存越先触顶。</p>\n<p>带宽侧的代价同样非线性。缓存 block 省掉了 MMA 与 TMEM 往返，却仍要把上一步 feature 从显存读回、施加缩放或低秩补偿后再写回，读写量与 block 输出规模同阶。设缓存命中比例为 $\\rho$，则每步实际访存约为 $(1-\\rho)$ 次全量计算访存加上 $\\rho$ 次缓存读写，当 $\\rho$ 逼近 1 时系统从算力受限转为带宽受限，SM 利用率下降而 HBM 流量不降。跨卡场景更敏感：若 block 被切分到不同 rank，缓存 feature 的复用需要一次集合通信对齐，NVLink 5 上的 all-gather 延迟会直接进入关键路径，跳步省下的计算时间可能被通信吃掉。</p>\n<p>尾延迟是这套方案最隐蔽的失效点。贡献分数 $s_l$ 依赖 prompt 与分辨率，同一批次内不同请求的可缓存 block 集合并不一致，导致各请求的实际计算量离散。P99 端到端时延由最慢的那条请求决定：一条纹理密集或含文字区域的 prompt 会把多数 block 判为高贡献而全量重算，其耗时接近未优化基线，而其余请求早已完成，形成长尾。少步采样（4–8 步）下相似度下降、收益收窄，缓存误差逐步累积，纹理与文字区域先出现模糊或笔画断裂，且难以通过后处理修复；每 N 步重新评估贡献分数会引入周期性尖峰，评估步的计算量回到全量水平，尾延迟随之抬升。</p>\n<p>工程判断落在阈值校准与容量预留的耦合上：跨业务直接复用 $\\tau_l$ 会造成部分请求画质骤降，必须按业务重新标定；缓存容量要按最坏请求的 block 集合预留而非均值，否则高分辨率大批量下显存先崩。功耗层面，跳步降低的是计算 block 的瞬时功耗，缓存读写与周期性重评估维持了内存子系统的基础功耗，整卡功耗曲线变得平坦而非同比下降，机架级供电裕度不能按跳步比例线性折算。</p>\n<h3 id=\"alg-feature-cache-skip-sec-40\">四十 · 精度失效的三种指纹与定位手法</h3>\n<p>缓存跳步的精度问题不是均匀退化，而是有明确的空间与结构指纹。第一种指纹是<strong>纹理高频先崩</strong>：缓存 block 复用上一步 feature，等价于在残差维度上引入一阶滞后，高频分量在连续复用中相位漂移，表现为织物、毛发、皮肤毛孔出现方向性涂抹感。第二种是<strong>文字笔画断裂</strong>：字形边缘属于低残差但高语义敏感的区域，贡献分数 $s_l$ 按 L2 相对范数排序时，笔画区域的能量占比小，容易被误判为低贡献 block 而缓存，结果横竖笔画出现断口或粘连。第三种是<strong>跨步漂移</strong>：少步采样（4–8 步）下每步的 $\\Delta_l^t$ 本身就大，缓存误差没有足够的后续步去吸收，误差沿 $t$ 单调累积，末步出现整体色偏或结构塌陷。</p>\n<p>定位手法要按数据流反查。第一步，把每步每 block 的 $s_l$ 与 $\\alpha_l$ 落盘成时间序列，观察被缓存 block 的 $s_l$ 是否在重新评估周期 $N$ 内单调上升——若上升，说明阈值 $\\tau$ 偏松，误差在累积而非被抑制。第二步，做<strong>逐 block 回算对照</strong>：对同一 latent 与 prompt，强制某几个 block 走全量计算，其余缓存，比较输出 latent 的逐通道差值图；差值集中在文字区域即证实笔画断裂来自该 block 的误缓存。第三步，用残差补偿项 $\\Delta_l$ 的范数做健康度指标，若 $\\|\\Delta_l\\|$ 与被缓存 block 的 $\\alpha_l$ 缩放后残差之比持续偏离预热期统计，说明低秩补偿已跟不上分布偏移。工程上把这三项做成每请求的轻量探针，只在采样后对 latent 做一次高频能量统计（拉普拉斯响应均值），低于预热基线即标记可疑请求，代价是一次卷积级开销，相对整条 DiT 前向可忽略。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-41\">四十一 · OOM 的真实来源：feature 常驻与批内峰值叠加</h3>\n<p>缓存 feature 常驻显存是这套方法最容易被低估的代价。容量按 block 数 × 分辨率 token 数 × 批大小 × 精度字节估算：以 24 个 block、1024 分辨率量级的 token 规模、批 4、FP16 计，单是缓存池就吃掉数 GB 量级，且这部分显存<strong>不随计算量下降而释放</strong>——省了算力，却把显存钉死。真正的 OOM 往往不是稳态容量不足，而是<strong>批内峰值叠加</strong>：连续批处理下新请求进入时，旧请求的缓存池尚未回收，新请求的预热阶段又要同时保留全量计算的中间激活与新建缓存，瞬时峰值可达稳态的两倍。</p>\n<p>诊断要区分两类曲线：稳态占用曲线看缓存池是否按 block 数线性增长，若增长斜率超过预估，说明某些 block 的缓存未被复用却在重复分配；峰值曲线看预热步与批切换点的尖峰，若尖峰宽度超过一个采样步，说明回收时机滞后。缓解手段有三条：其一，缓存池按<strong>块粒度分页</strong>，只对当前批内活跃请求的 block 分配物理页，空闲页立即归还，避免按最大批预留；其二，预热阶段不建缓存，等贡献分数稳定后再按需分配，把预热期的全量激活与缓存池错峰；其三，高分辨率大批量时把缓存精度降到 FP8 甚至 NVFP4 存储、计算时反量化，用带宽换容量——代价是每次读缓存多一次反量化指令，但相对重算一个 block 的 GEMM 仍是净赚。若显存仍逼近上限，正确判断是<strong>降批而非降阈值</strong>：降阈值会让更多 block 走全量计算，吞吐收益归零却仍占着缓存池，是最差的组合。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-42\">四十二 · 批抖动与路由不均：两个不同层面的失衡</h3>\n<p>批抖动来自<strong>每请求的计算图不同</strong>。缓存跳步让不同请求在同一批内走不同数量的 block，批内计算量不再齐整，GPU 的 SM 占用出现空洞：一个请求缓存了 40% 的 block，它的前向时间短，先完成后等待同批其他请求，形成批内拖尾。连续批处理调度器若按固定 token 预算组批，会把长短不一的请求硬塞在一起，抖动被放大成批级尾延迟。诊断看两个量：批内各请求的实际 block 计算数方差，以及批完成时间的 P99 与中位数之比。前者大方差说明阈值校准不一致或 prompt 差异过大，后者比值偏高说明组批策略没有按计算量分桶。</p>\n<p>路由不均则是另一层：贡献分数依赖 prompt 与分辨率，同一阈值下，文字密集 prompt 的高贡献 block 集中在浅层与深层两端，风景类 prompt 集中在中间层，导致不同请求的计算量分布形状不同。若服务端按请求类型混跑而不做分桶，GPU 上同时驻留的 kernel 形状差异大，tcgen05 的 MMA 利用率被拉低。工程做法是按<strong>贡献分数向量做聚类分桶</strong>，同桶请求共享阈值与批策略，桶间独立排队；分桶键可用预热期统计的 block 计算数占比与浅深层分布，桶数控制在个位数以免调度碎片化。代价是桶间负载不均时需要跨桶借调，借调逻辑本身引入调度延迟，因此桶数不宜过细。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-43\">四十三 · 尾延迟尖刺的三个触发点</h3>\n<p>P99 尖刺不来自平均路径，而来自三个确定性触发点。第一是<strong>重新评估周期 $N$ 的同步点</strong>：每 N 步重算贡献分数需要一次全量或近全量的 block 前向，这一步的计算量突然回到无缓存水平，若与批内其他请求的采样步对齐，形成周期性尖峰。缓解是把重评估做成<strong>滚动式</strong>：每步只重评一部分 block，把一次大尖峰摊成 N 次小增量，代价是分数更新有滞后，阈值需留更紧的余量。第二是<strong>缓存池换页</strong>：新请求进入触发分页分配，若分配路径上有同步等待，尖刺宽度等于一次分配延迟乘以批内请求数。第三是<strong>跨业务阈值切换</strong>：请求被路由到不同桶时若触发阈值重载与缓存失效，该请求的首步退化为全量计算，尾延迟直接跳到无优化基线。</p>\n<p>监控上，尾延迟要按<strong>触发点标签</strong>拆分统计，而不是只看端到端 P99：把采样步耗时按“普通步 / 重评估步 / 首步 / 换页步”打标，分别出分位数曲线。若尖刺集中在重评估步，说明 $N$ 太小或滚动化不足；若集中在首步，说明桶切换或缓存冷启动问题。容量规划上，SLO 以 P99 为主时，必须把重评估步的耗时计入预算，否则平均值达标而尾延迟违约。一个具体判断：当重评估步耗时超过普通步的两倍，且其占比超过总步数的 $1/N$，端到端 P99 会被这一步主导，此时应优先滚动化而非调阈值。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-44\">四十四 · 回滚路径：分级降级而非一刀切关闭</h3>\n<p>回滚不能只有“关掉缓存跳步”一个开关，那会让吞吐瞬间跌回基线并可能引发雪崩。应设计三级降级。一级是<strong>收紧阈值</strong>：把 $\\tau$ 上调，减少被缓存 block 数，画质恢复但收益收窄，切换是热更新，无需重建缓存池。二级是<strong>关闭残差补偿的低秩项、只保留缩放</strong>：低秩补偿在分布偏移时可能引入伪影，退化到纯缩放 $\\alpha_l$ 更保守，代价是误差抑制变弱、需要更紧的阈值配合。三级才是<strong>整请求退出缓存路径</strong>，且应只对可疑请求生效，而非全服务关闭——按第一节的高频能量探针标记可疑请求，单独走全量计算，其余请求维持优化。</p>\n<p>回滚的触发条件要可量化：单请求级用探针指标越界；服务级用分桶后的画质投诉率或人工抽检不合格率超过预设线；系统级用尾延迟尖刺频率超过 SLO 容忍。回滚动作必须<strong>幂等且可逆</strong>，阈值与补偿系数的每次变更都记录版本号，便于在画质与吞吐之间做 A/B 对照。工程判断上，跨业务复用同一套阈值是这套方法最常见的翻车点：新业务上线前必须用该业务的 prompt 分布重跑预热校准，产出独立的 $\\tau$ 与 $\\alpha_l$ 表，并把校准结果纳入发布门禁；没有校准表的业务默认走全量计算，直到校准完成。这样把“画质骤降”从线上事故变成发布期可控的准入问题。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-45\">四十五 · 缓存跳步的失效边界与在线诊断：从画质崩点到显存反噬</h3>\n\n<p>这套方案真正的工程风险不在“能不能跳”，而在“跳错了还看不出来”。缓存 block 的误差不会以异常值形式暴露，而是以分布漂移的形式渗入后续步：某层 feature 被复用后，下一层基于这份陈旧输入继续前向，误差沿 block 链与扩散步两个维度同时累积。用相对残差分数刻画这一过程：<div class=\"formula\">$$s_l=\\frac{\\|h_l^{(t)}-h_l^{(t-1)}\\|_2}{\\|h_l^{(t-1)}\\|_2},\\quad h_l^{(t)}=\\begin{cases}\\alpha_l h_l^{(t-1)}+\\Delta_l &amp; s_l&lt;\\tau\\\\ \\mathrm{Block}_l(h_{l-1}^{(t)}) &amp; s_l\\ge\\tau\\end{cases}$$</div>阈值 $\\tau$ 定得松，$s_l$ 在少步采样下本就偏大，被误判为可缓存的 block 增多，纹理细节与文字区域最先崩——表现为笔画断裂、边缘糊化，且后处理锐化无法恢复已丢失的高频结构。诊断上不能只看端到端 P99，必须在管线内挂每 block 的 $s_l$ 采样探针：把实际计算步的 $s_l$ 与缓存步的预测值对比，若连续若干步出现“缓存 block 的 $s_l$ 反超阈值”即判定漂移，触发提前重评估（而非等满 N 步）。代价是探针本身要读回 feature 范数，属轻量归约，但会打断 block 间的纯异步流水，单请求增加可测的同步开销。</p>\n\n<p>第二类失效是显存反噬。缓存 feature 常驻显存，容量按 block 数×分辨率×批大小预留，KV 概念在此不适用。分辨率翻倍、批大小从 1 抬到 8 时，缓存占用接近全量计算所需的激活峰值，收益被抵消甚至触发 OOM；而 OOM 往往发生在批内某个高分辨率请求上，表现为整批失败而非单请求降级。工程判断是给缓存容量设硬上限并按显存档位反推最大批：先算 $C_{\\text{cache}}=N_{\\text{block}}\\times H\\times W\\times d\\times B$，再与权重、激活峰值做预算，超限时降批而非降阈值——降阈值会直接牺牲画质且不可控。监控项应包含缓存占用率与批内分辨率方差，方差大意味着批抖动风险高。</p>\n\n<p>第三类失效是路由不均与尾延迟尖刺。贡献分数依赖 prompt 与分辨率，跨业务直接复用阈值会让部分请求几乎全 block 重算、另一部分几乎全缓存，形成批内计算量双峰：短请求快、复杂 prompt 慢，连续批处理下调度器按 token 步推进，慢请求拖住整个 batch 的迭代节奏，P99 被单条长尾拉高。表现为吞吐看似正常而尾延迟尖刺频发。诊断抓手是每请求的“实际计算 block 比例”直方图，双峰即路由不均；此时应按业务重新标定 $\\tau$ 与 $\\alpha_l$，而非全局调参。回滚策略要分层：先关残差补偿的低秩项（最易引入分布偏移），再抬阈值减少缓存 block，最后整体禁用跳步回到全量前向——三级开关均可在请求级灰度，避免一次全量回滚吃掉全部吞吐收益。每 N 步重评估贡献分数是防漂移的底线机制，但 N 过大时漂移已在画质上显形，N 过小则重评估本身成为延迟尖刺源，需与探针告警联动动态收紧。</p>\n<h3 id=\"alg-feature-cache-skip-sec-46\">四十六 · 同族算法的坐标系：改权重、改数值、改计算图</h3>\n<p>把特征缓存与块级跳步放回它真正的邻居中间，坐标系只有一根轴：<strong>推理期到底改了什么</strong>。少步蒸馏改的是权重——学生模型被重新训练成用 4–8 步逼近教师的高步数轨迹，步数从源头被砍掉；量化（FP8、NVFP4、MX 分块）改的是数值精度——计算图结构不变，只是每个 GEMM 与注意力的操作数位宽变窄；块级稀疏注意力改的是 token 交互——block 仍然被完整调度，只是注意力矩阵里大量 token 对被判定为可忽略。特征缓存与块级跳步改的是<strong>前向计算图本身</strong>：block 还在，参数没动，精度没动，只是某些 block 这一步不执行，直接读上一步的 feature。这个定位决定了三件事：它不需要重训、不需要校准数据集、不需要改 kernel 的数值路径，因此插入成本最低；但也决定了它的收益上限被“步间相似度”这一数据属性死死卡住，而不像蒸馏那样可以从根上改变步数。</p>\n<p>工程上最容易犯的错是把这四类方法当成互斥选项去选一个。实际上它们的作用点正交：蒸馏压缩步数维度 $T$，缓存跳步压缩每步的 block 维度 $L$，量化压缩每次 block 计算的位宽与带宽，稀疏注意力压缩 token 维度。端到端时延近似正比于 $T\\cdot L_{\\text{compute}}\\cdot(\\text{每 block 代价})$，三个因子各自被一类方法压低，因此叠加是自然的，冲突只发生在资源侧——缓存 feature 要占显存，量化省下的显存可能正好被它吃掉。</p>\n<div class=\"formula\">$$\\text{Latency}\\;\\propto\\;T\\;\\cdot\\;L_{\\text{compute}}\\;\\cdot\\;\\text{Cost}_{\\text{block}}(\\text{precision}),\\qquad L_{\\text{compute}}=L\\cdot(1-\\rho_{\\text{skip}})$$</div>\n<p>其中 $\\rho_{\\text{skip}}$ 是可缓存 block 占比，由阈值 $\\tau$ 与贡献分数分布决定。这个式子说明：当 $T$ 已经被蒸馏压到 4–8 时，$L_{\\text{compute}}$ 的压缩空间依然存在，但 $\\rho_{\\text{skip}}$ 会显著下降——因为少步采样下相邻步的 feature 差异变大，更多 block 的 $s_l$ 越过阈值。这正是本方法与其他方法叠加时唯一需要重新标定的耦合点。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-47\">四十七 · 决策表：按场景条件选型</h3>\n<p>下表把选型条件写成可判定的工程判据，而不是“看情况”。每一行的判据都对应一个可测量的量：步数 $T$、分辨率与批大小决定的显存余量、是否有重训预算、SLO 是 P99 时延还是吞吐。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>场景条件</th><th>首选</th><th>次选/叠加</th><th>不选缓存跳步的理由</th></tr>\n</thead>\n<tbody>\n<tr><td>高步数教师模型（$T$ 大）、无重训预算</td><td>特征缓存与块级跳步</td><td>FP8/NVFP4 量化</td><td>—（本场景正是主战场）</td></tr>\n<tr><td>已有蒸馏学生、$T$ 已压到 4–8</td><td>量化 + 稀疏注意力</td><td>缓存跳步仅作小幅补充</td><td>步间相似度下降，$\\rho_{\\text{skip}}$ 收窄，收益不足以抵消显存开销</td></tr>\n<tr><td>视频多帧、帧间与步间双重相似</td><td>缓存跳步（收益最大）</td><td>分块 VAE 解码并行</td><td>—</td></tr>\n<tr><td>显存吃紧、批大小被迫压到 1</td><td>量化优先</td><td>缓存跳步需先算显存账</td><td>缓存 feature 常驻，高分辨率下占用接近全量计算</td></tr>\n<tr><td>文字/细笔画密集的商用出图</td><td>全量计算或高阈值跳步</td><td>量化</td><td>缓存误差先在文字区域崩，后处理无法修复</td></tr>\n<tr><td>多业务共用一套服务、prompt 分布漂移</td><td>按业务分桶校准阈值</td><td>缓存跳步 + 每 N 步重评估</td><td>跨业务复用单一 $\\tau$ 会造成部分请求画质骤降</td></tr>\n</tbody>\n</table>\n<p>读这张表的正确方式是看第三列：<strong>什么条件下不该用它</strong>比什么条件下该用它更有信息量。缓存跳步的失效不是渐变而是阶跃——阈值一旦偏大，某些请求的画质不是“稍差”而是“骤降”，这在混布服务里是不可接受的尾部风险。因此选型的第一道闸门不是性能，而是业务对画质尾部的要求。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-48\">四十八 · 与少步蒸馏的耦合：正交但不同步</h3>\n<p>“正交”这个词容易被误读成“可以无脑叠加”。两者确实作用在不同维度，但它们的<strong>最优参数互相牵制</strong>。蒸馏把 $T$ 压小之后，相邻步的 feature 差异 $\\|\\Delta_l^t\\|$ 相对增大，同一个 $\\tau$ 下更多 block 被判为需重算，$\\rho_{\\text{skip}}$ 下降；反过来，如果先按高步数场景标定了 $\\tau$，再换到蒸馏学生上，阈值偏大，缓存误差在仅有的几步里被放大——因为每一步的误差都没有后续步去“纠正”，少步采样下误差累积路径更短、更陡。</p>\n<p>可操作的耦合策略是<strong>按 $T$ 反比调 $\\tau$</strong>：步数越少，阈值越保守，甚至退化为只缓存最末尾几个低贡献 block。伪代码层面的判断很直接：</p>\n<div class=\"formula\">$$\\tau_{\\text{eff}}=\\tau_{0}\\cdot\\frac{T_{\\text{ref}}}{T},\\qquad \\text{re-evaluate } s_l \\text{ every } N \\text{ steps}$$</div>\n<p>这里 $T_{\\text{ref}}$ 是标定阈值时用的参考步数，$N$ 是重评估周期。代价方面，重评估本身要跑一次全量前向拿贡献分数，等于每 $N$ 步插入一次“无收益步”，摊销后对吞吐的侵蚀约为 $1/N$ 量级；$N$ 取太小则收益被吃掉，取太大则误差漂移无人管。工程上把 $N$ 与采样器步长绑定，让重评估落在噪声水平变化较大的步上，比固定周期更稳。具体例子：一个 50 步教师配 8 步蒸馏学生的双档服务，教师档用 $\\tau_0$、学生档用约 6 倍保守的阈值，两档共享同一套 block 贡献排序逻辑，只是阈值分档——这样避免了为两档各维护一套缓存策略。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-49\">四十九 · 与量化的耦合：显存账要先算</h3>\n<p>量化与缓存跳步在计算侧是加法的：量化把每个被计算的 block 变便宜，跳步把被计算的 block 变少，两者乘起来才是端到端收益。但在显存侧它们是<strong>互相挤占</strong>的。缓存 feature 常驻显存，容量正比于 block 数 × 分辨率 × 批大小 × 每元素字节数；量化恰好压缩的是“每元素字节数”这一项，于是量化省出来的显存很容易被缓存池重新占满，吞吐收益被抵消——这正是失败模式里“高分辨率大批量时显存占用接近全量计算”的机制来源。</p>\n<div class=\"formula\">$$M_{\\text{cache}}\\approx N_{\\text{block}}\\cdot H\\cdot W\\cdot B\\cdot b,\\qquad \\text{headroom}=M_{\\text{total}}-M_{\\text{weights}}-M_{\\text{act}}-M_{\\text{cache}}$$</div>\n<p>其中 $b$ 是缓存 feature 的每元素字节数。工程判断的顺序应该是：先定量化档位（决定 $b$ 与权重占用），再算 headroom，最后反推可缓存的最大 block 数与批大小 $B$。如果 headroom 不足以容纳全部低贡献 block 的 feature，就只缓存贡献分数最低的那一档，把 $\\rho_{\\text{skip}}$ 主动调低——这是用收益换稳定，而不是让运行时去 OOM。另一个细节：缓存 feature 的位宽不必与计算位宽一致，用更低精度存缓存、计算时再升位，可以在几乎不影响画质的前提下把 $M_{\\text{cache}}$ 压下来，代价是每次读取多一次转换，带宽开销增加，需要和 block 计算的节省做对比。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-50\">五十 · 与块级稀疏注意力的边界：跳 block 还是跳 token</h3>\n<p>两者名字里都有“块”，但跳过的东西完全不同，混用会直接导致实现错误。块级稀疏注意力跳过的是 token 之间的交互——block 仍被调度，只是注意力矩阵中大量 token 对被判定为无需计算；特征缓存跳步跳过的是<strong>整个 block 的前向</strong>，包括它的 GEMM、归一化与残差，token 一个不少地流过剩下的 block。因此前者省的是注意力那部分的算力与带宽，后者省的是 block 级的 GEMM 与激活读写；前者对长序列、高分辨率 token 数敏感，后者对步数与 block 数敏感。</p>\n<p>选型判据可以写得很硬：如果瓶颈在注意力（长序列、视频多帧的 token 爆炸），先上稀疏注意力；如果瓶颈在逐 block 的 GEMM 且步间相似度高，先上缓存跳步。两者叠加时要注意顺序——缓存跳步会让被跳过的 block 完全不产生注意力，稀疏注意力的稀疏模式若依赖上一步的注意力统计，就会读到过期信息。稳妥做法是把稀疏模式的估计放在计算 block 上做，缓存 block 沿用上一步的模式，并在每 $N$ 步重评估时同步刷新两者。代价上，稀疏注意力省的是带宽与注意力算力，缓存跳步省的是 block 算力但增加显存常驻，两者的资源账要分开记，不能用一个“加速比”笼统相加。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-51\">五十一 · 适用条件的量化判据与工程落点</h3>\n<p>把适用条件写成可执行的判据，而不是定性描述。第一条：<strong>步间相对残差的中位数</strong>。预热若干步后统计所有 block 的 $s_l$ 分布，若中位数显著低于候选阈值，说明大部分 block 天然可缓存，收益确定性高；若中位数与阈值同量级，说明分布平坦、跳步选择对阈值极度敏感，此时应放弃跳步或只缓存最尾部的一小撮 block。第二条：<strong>画质尾部而非均值</strong>。缓存误差在文字与纹理区域先崩，均值指标看不出来，必须用固定 prompt 集做逐请求的画质下限检查，把“最差的那一档”作为验收标准。第三条：<strong>显存 headroom 与 $\\rho_{\\text{skip}}$ 的乘积</strong>，两者共同决定实际吞吐增益，任一不足都让收益归零。</p>\n<p>最后落在工程判断上：特征缓存与块级跳步的正确位置是<strong>“高步数、无重训预算、显存有余”三者同时成立时的第一选择</strong>，并且它应当被实现为一个可开关、阈值可按业务分桶、每 $N$ 步强制重评估的推理期插件，而不是一个全局默认开启的优化。原因很直接——它的失效模式是画质阶跃式下降且不可后处理修复，而它的收益又高度依赖 prompt 与分辨率分布。把阈值校准、重评估周期、缓存池容量三个旋钮暴露给服务层，按业务桶分别标定，才能既拿到 30–50% 的 block 计算节省，又不让某个分布外的请求把整条服务的画质口碑拖下水。这也解释了为什么它和量化、蒸馏的叠加必须带着显存账与阈值重标定一起做：三个因子里有两个是数据依赖的，唯一确定的是计算图可以被改写这件事本身。</p>\n\n<h3 id=\"alg-feature-cache-skip-sec-52\">五十二 · 同族算法怎么选：跳步、蒸馏与量化的边界判据</h3>\n<p>本方法在算法谱系里的坐标必须说清楚：它不改权重（区别于少步蒸馏）、不改数值精度（区别于 FP8/NVFP4 量化）、也不改 token 交互（区别于块级稀疏注意力），只改前向计算图，属训练-free 的推理期跳步。因此选型的第一判据不是\"哪个更快\"，而是\"瓶颈在哪一层\"。若端到端时延被步数线性放大、且相邻步 block 输出相似度高，跳步直接命中；若瓶颈是权重带宽或数值吞吐，量化的收益更确定；若瓶颈是采样步数本身太多，蒸馏才是治本手段。三者正交，可叠加，但叠加顺序影响收益归因：先量化压低单 block 成本，再跳步减少 block 数，最后用蒸馏压缩步数，此时端到端加速近似为各因子相乘而非相加。</p>\n<div class=\"formula\">$$\\text{Speedup}_{\\text{total}}\\approx\\frac{L}{L_{\\text{compute}}}\\times\\frac{1}{q}\\times\\frac{T}{T_{\\text{distill}}}$$</div>\n<p>决策表按四个维度切分，每一行都对应一个可观测的系统代价：</p>\n<table class=\"mini\"><thead><tr><th>场景特征</th><th>首选</th><th>关键代价</th></tr></thead><tbody><tr><td>高步数教师模型、视频多帧、步间相似度高</td><td>块级跳步</td><td>缓存 feature 常驻显存，按 block 数×分辨率×批大小预留</td></tr><tr><td>步数已压到 4–8 步</td><td>少步蒸馏</td><td>需重训，跳步收益收窄至可忽略</td></tr><tr><td>显存带宽受限、批大小上不去</td><td>FP8/NVFP4 量化</td><td>数值精度损失，与跳步可叠加</td></tr><tr><td>跨业务复用同一管线</td><td>量化+蒸馏（阈值稳定）</td><td>跳步阈值需逐业务重标定，运维成本高</td></tr></tbody></table>\n<p>失效条件集中在两处。其一是步数下限：当采样步数降到 4–8 步，相邻步相似度下降，贡献分数 $s_l$ 普遍越过阈值 $\\tau$，可缓存 block 数骤减，收益收窄而残差补偿的误差却在少步下更易累积——纹理细节与文字区域先出现模糊或笔画断裂，且难以通过后处理修复。其二是跨业务漂移：贡献分数依赖 prompt 与分辨率，直接复用他业务标定的 $\\tau$ 会造成部分请求画质骤降，必须按业务重新校准，并把\"每 N 步重新评估贡献分数\"作为防止误差随步数漂移的常规动作。工程判断上，若单卡显存已被缓存 feature 吃掉接近全量计算的占用，吞吐收益会被抵消，此时应下调批大小或缩小可缓存 block 集合，而不是继续调低 $\\tau$ 换取名义上的跳步率。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2025 · VAE 解码与潜空间压缩</td></tr><tr><td>解决什么</td><td>相邻扩散步的 DiT block 输出高度相似，逐步全量计算浪费算力，尤其在高步数教师模型与视频多帧场景下时延被线性放…</td></tr><tr><td>一句话机制</td><td>按 block 统计相邻步残差贡献度，对贡献低于阈值的 block 直接复用上一步输出，仅对高贡献 block 重算，…</td></tr><tr><td>代价与失效</td><td>缓存误差在少步采样下更易累积，纹理细节与文字区域先崩；贡献分数依赖 prompt 与分辨率，跨业务需重新校准阈值，否则画质不稳</td></tr><tr><td>后继</td><td>混合分辨率补丁调度</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-feature-cache-skip · 共 8 个片段</p>\n";break;}}})();
